      if (t - palAt > 30) { pal = palette(); sea = seaState(); palAt = t; }
      if (!B.hiP) { B.hiP = ctx.createPattern(tex.hi, 'repeat'); B.loP = ctx.createPattern(tex.lo, 'repeat'); }
