Object.assign(ICON, {
  contacts: _s('<circle cx="12" cy="12" r="9.2"/><circle cx="12" cy="9.8" r="3.3"/><path d="M5.9 18.6c1.4-2.4 3.6-3.7 6.1-3.7s4.7 1.3 6.1 3.7"/>'),
  wallpaper: _s('<rect x="3" y="3" width="18" height="18" rx="3"/><path d="M3 15l5-5 4 4 3-3 6 6"/><circle cx="15.5" cy="8.5" r="1.6"/>'),
  phone: _s('<path d="M5 3.5h3.2l1.6 4.2-2 1.4a11 11 0 006.1 6.1l1.4-2 4.2 1.6V18a2.5 2.5 0 01-2.5 2.5A15.5 15.5 0 013 6a2.5 2.5 0 012-2.5z"/>'),
  pin: _s('<path d="M12 21s-6.5-5.6-6.5-11a6.5 6.5 0 0113 0c0 5.4-6.5 11-6.5 11z"/><circle cx="12" cy="10" r="2.4"/>'),
  addPerson: _s('<circle cx="10" cy="8" r="3.8"/><path d="M3 20c1-3.5 3.7-5.2 7-5.2 1.3 0 2.5.3 3.6.8M18.5 13v7M15 16.5h7"/>'),
  share: _s('<path d="M12 3.5v12M7.5 8L12 3.5 16.5 8"/><path d="M6 11.5H5a1.5 1.5 0 00-1.5 1.5v6A1.5 1.5 0 005 20.5h14a1.5 1.5 0 001.5-1.5v-6a1.5 1.5 0 00-1.5-1.5h-1"/>'),
});

Object.assign(CrowMessengerEmail.prototype, {
  // ── backgrounds ──────────────────────────────────────────────────────
  _bgFor(key) {
    const b = this._s.backgrounds || {};
    const v = (key && b[key]) || b['*'] || '';
    return v === 'none' ? '' : v;
  },

  // show a page's background, and run its Live Wallpaper only while the page is on screen
  _bgAttach(page, keyOf) {
    const el = page.el;
    let live = null, liveId = null, showing = true;
    const apply = () => {
      const v = this._bgFor(keyOf());
      let box = el.querySelector(':scope > .ce-bg');
      if (!v) {
        if (live) { live.stop(); live = null; liveId = null; }
        box?.remove(); el.classList.remove('has-bg');
        return;
      }
      if (!box) { box = document.createElement('div'); box.className = 'ce-bg'; el.prepend(box); }
      el.classList.add('has-bg');
      if (v.startsWith('live:')) {
        const id = v.slice(5);
        box.style.backgroundImage = '';
        if (showing && liveId !== id) { live?.stop(); live = new CrowLiveWallpaper(box, id, this._hass); liveId = id; }
        if (!showing && live) { live.stop(); live = null; liveId = null; }
      } else {
        if (live) { live.stop(); live = null; liveId = null; }
        box.style.backgroundImage = `url("${v}")`;
      }
    };
    const { refresh, onShow, onHide, destroy } = page;
    page.refresh = (what, extra) => { refresh?.(what, extra); if (['all', 'backgrounds', 'back'].includes(what)) apply(); };
    page.onShow = () => { showing = true; onShow?.(); apply(); };
    page.onHide = () => { showing = false; onHide?.(); live?.stop(); live = null; liveId = null; };
    page.destroy = () => { destroy?.(); live?.stop(); live = null; };
    page.bgKey = keyOf;
    return page;
  },

  _bgLabel() {
    const v = (this._s.backgrounds || {})['*'] || '';
    return !v || v === 'none' ? 'None' : v.startsWith('live:') ? (ceLiveInfo(v.slice(5))?.name || 'Live Wallpaper') : 'Photo';
  },

  _bgItems(key, label) {
    const b = this._s.backgrounds || {};
    const items = [
      { text: `Photo for ${label}…`, value: 'bg:this', icon: 'image' },
      { text: 'Photo for Everywhere…', value: 'bg:all', icon: 'wallpaper' },
      { text: 'Live Wallpaper…', value: 'bg:live', icon: 'magic' },
    ];
    if (b[key] && b[key] !== 'none') items.push({ sep: true }, { text: `Remove from ${label}`, value: 'bg:remove', icon: 'x' });
    else if (b['*'] && key !== '*') items.push({ sep: true }, { text: 'Remove Everywhere', value: 'bg:removeall', icon: 'x' });
    return items;
  },

  async _bgChoice(key, what, label) {
    try {
      if (what === 'live') { this._nav('live', { key, label }); return; }
      if (what === 'remove') {
        const b = this._s.backgrounds || {};
        await this._call('background/set', { key, image: b['*'] && key !== '*' ? 'none' : null });
        return;
      }
      if (what === 'removeall') { await this._call('background/set', { key: '*', image: null }); return; }
      const target = what === 'all' ? '*' : key;
      const input = document.createElement('input');
      input.type = 'file'; input.accept = 'image/*'; input.hidden = true;
      this._root.appendChild(input);
      input.addEventListener('change', async () => {
        const f = input.files[0]; input.remove();
        if (!f) return;
        try {
          this._toast('Setting background…');
          await this._call('background/set', { key: target, image: await fileToBackground(f) });
          this._toast(target === '*' ? 'Background set everywhere' : `Background set for ${label}`);
        } catch (err) { this._err(err); }
      });
      input.click();
    } catch (err) { this._err(err); }
  },

  _pg_live({ key, label }) {
    const previews = new Map();
    let scope = key !== '*' && (this._s.backgrounds || {})[key] ? 'this' : '*';
    const k = () => (scope === '*' ? '*' : key);
    const grid = `<div class="pick" data-id="none" role="button"><div class="tile none-tile">${ICON.x}<span class="ck">${ICON.check}</span></div><div class="nm">None</div></div>`
      + CE_LIVE.map(l => `<div class="pick" data-id="${l.id}" role="button"><div class="tile" style="background:${l.thumb}"><div class="live" data-live="${l.id}"></div><span class="ck">${ICON.check}</span></div><div class="nm">${esc(l.name)}</div></div>`).join('');
    const el = this._simplePage('Live Wallpaper', `${key !== '*' ? `<div class="segc" style="margin-bottom:16px"><button data-scope="this">${esc(label)}</button><button data-scope="*">Everywhere</button></div>` : ''}<div class="pick-grid">${grid}</div>
      <div class="pick-note">Live Wallpapers move gently behind your email, and pause when they're not on screen.</div>`);
    this._scrollTitle(el);
    const draw = () => {
      el.querySelectorAll('[data-scope]').forEach(b => b.classList.toggle('on', b.dataset.scope === scope));
      const v = scope === '*' ? (this._s.backgrounds || {})['*'] : this._bgFor(key);
      const cur = !v || v === 'none' ? 'none' : v.startsWith('live:') ? v.slice(5) : '';
      el.querySelectorAll('.pick').forEach(p => p.classList.toggle('on', p.dataset.id === cur));
    };
    el.addEventListener('click', async (e) => {
      if (e.target.closest('[data-a="back"]')) { this._back(); return; }
      const sc = e.target.closest('[data-scope]')?.dataset.scope;
      if (sc) { scope = sc; draw(); return; }
      const p = e.target.closest('.pick');
      if (!p) return;
      try {
        if (p.dataset.id === 'none') await this._call('background/set', { key: k(), image: k() !== '*' && (this._s.backgrounds || {})['*'] ? 'none' : null });
        else { await this._call('background/set', { key: k(), image: `live:${p.dataset.id}` }); this._toast(`${ceLiveInfo(p.dataset.id)?.name} set`); }
      } catch (err) { this._err(err); }
    });
    return {
      el,
      refresh: () => draw(),
      onShow: () => el.querySelectorAll('[data-live]').forEach(box => { if (!previews.has(box)) previews.set(box, new CrowLiveWallpaper(box, box.dataset.live, this._hass)); }),
      onHide: () => { previews.forEach(w => w.stop()); previews.clear(); },
      destroy: () => { previews.forEach(w => w.stop()); previews.clear(); },
    };
  },

  // ── contacts ─────────────────────────────────────────────────────────
  _contactList() { return this._s.contacts || []; },
  _contact(id) { return this._contactList().find(c => c.id === id); },
  _contactByEmail(email) {
    const e = String(email || '').toLowerCase();
    return e ? this._contactList().find(c => (c.emails || []).some(x => x.value === e)) : null;
  },
  _contactAv(c, size) {
    const name = contactName(c) || (c.emails || [])[0]?.value || '?';
    if (c.photo) return `<div class="av" style="width:${size}px;height:${size}px"><img src="${esc(c.photo)}" alt=""></div>`;
    return this._avatar({ name, email: (c.emails || [])[0]?.value || name }, size);
  },
  _sortedContacts(q = '') {
    q = q.trim().toLowerCase();
    let list = [...this._contactList()];
    if (q) list = list.filter(c => [contactName(c), c.company, c.nickname, ...(c.emails || []).map(e => e.value), ...(c.phones || []).map(p => p.value)].filter(Boolean).join(' ').toLowerCase().includes(q));
    list.sort((a, b) => {
      const la = contactLetter(a, 'last'), lb = contactLetter(b, 'last');
      if ((la === '#') !== (lb === '#')) return la === '#' ? 1 : -1;
      return contactSortKey(a, 'last').localeCompare(contactSortKey(b, 'last'), undefined, { sensitivity: 'base' });
    });
    return list;
  },

  _pg_contacts() {
    const el = this._el(`<div class="contactspg">
      <div class="top compact"><button class="cb g" data-a="back" aria-label="Back">${ICON.back}</button><div class="ttl"><div class="tt">Contacts</div><div class="ts"></div></div>
        <div class="right"><button class="cb g" data-a="more" aria-label="More">${ICON.more}</button></div></div>
      <div class="edge top tall"></div>
      <div class="scroll"><div class="ct-list"></div></div>
      <div class="az"></div>
      <div class="bottom">
        <div class="searchbar g">${ICON.search}<input type="search" placeholder="Search" autocomplete="off" enterkeyhint="search"><button class="sb-x" data-a="clear" hidden>${ICON.x}</button></div>
        <button class="cb g" data-a="add" aria-label="New Contact">${ICON.plus}</button>
      </div>
      <input type="file" class="f-vcf" accept=".vcf,text/vcard,text/x-vcard" hidden></div>`);
    const listEl = el.querySelector('.ct-list'), scroll = el.querySelector('.scroll'), az = el.querySelector('.az');
    const input = el.querySelector('.searchbar input');
    const draw = () => {
      const q = input.value;
      el.querySelector('[data-a="clear"]').hidden = !q;
      const list = this._sortedContacts(q);
      el.querySelector('.ts').textContent = `${this._contactList().length} contact${this._contactList().length === 1 ? '' : 's'}`;
      let html = '', cur = null;
      for (const c of list) {
        const L = contactLetter(c, 'last');
        if (L !== cur && !q) { cur = L; html += `<div class="ct-sec" data-l="${L === '#' ? '~' : L}">${L}</div>`; }
        const email = (c.emails || [])[0]?.value || '';
        html += `<div class="ct-row" data-cid="${esc(c.id)}">${this._contactAv(c, 44)}<div style="min-width:0;flex:1"><div class="n">${esc(contactName(c) || email || 'No Name')}</div>${email || c.company ? `<div class="s">${esc(email || c.company)}</div>` : ''}</div>${(c.emails || []).some(e => this._isVip(e.value)) ? `<span class="vip">${ICON.starF}</span>` : ''}</div>`;
      }
      if (!list.length) html = q ? `<div class="empty"><b>No Results</b>No contacts match “${esc(q.trim())}”.</div>`
        : `<div class="empty"><b>No Contacts</b>Tap + to add someone, or use ⋯ to import a vCard from your iPhone or Android contacts.<br><br>Your contacts are private: no one else in your home can see them.</div>`;
      listEl.innerHTML = html;
      az.innerHTML = list.length > 8 && !q ? 'ABCDEFGHIJKLMNOPQRSTUVWXYZ#'.split('').map(l => `<b>${l}</b>`).join('') : '';
    };
    input.addEventListener('input', draw);
    el.querySelector('.f-vcf').addEventListener('change', async (e) => { const f = e.target.files[0]; e.target.value = ''; if (f) this._importVCards(f); });
    const jump = (x, y) => {
      const b = this.shadowRoot.elementFromPoint(x, y);
      if (!b || b.parentElement !== az) return;
      const secs = [...listEl.querySelectorAll('.ct-sec')];
      const t = secs.find(h => h.dataset.l >= (b.textContent === '#' ? '~' : b.textContent)) || secs[secs.length - 1];
      if (t) scroll.scrollTop = t.offsetTop - 70;
    };
    az.addEventListener('pointerdown', (e) => { e.preventDefault(); try { az.setPointerCapture(e.pointerId); } catch (err) { /* */ } jump(e.clientX, e.clientY); });
    az.addEventListener('pointermove', (e) => { if (e.buttons || e.pointerType === 'touch') jump(e.clientX, e.clientY); });
    el.addEventListener('click', async (e) => {
      const a = e.target.closest('[data-a]')?.dataset.a;
      if (a === 'back') { this._back(); return; }
      if (a === 'clear') { input.value = ''; draw(); return; }
      if (a === 'add') { this._nav('contactEdit', { prefill: {} }); return; }
      if (a === 'more') {
        const v = await this._menu(e.target.closest('button'), [
          { text: 'Import vCard…', value: 'import', icon: 'download' },
          { text: 'Add People You Email…', value: 'recent', icon: 'addPerson' },
          { sep: true },
          { text: 'Export All Contacts', value: 'export', icon: 'share', disabled: !this._contactList().length },
        ]);
        if (v === 'import') el.querySelector('.f-vcf').click();
        if (v === 'export') this._exportContacts(this._contactList(), 'Contacts.vcf');
        if (v === 'recent') this._addRecentPeople();
        return;
      }
      const row = e.target.closest('.ct-row');
      if (row) this._nav('contact', { cid: row.dataset.cid });
    });
    return { el, refresh: (what) => { if (['all', 'contacts', 'vips', 'back'].includes(what)) draw(); } };
  },

  // choose someone to email: your contacts first, then people you've emailed. Resolves { name, email } or null.
  _pickContact({ title = 'Contacts', exclude = [] } = {}) {
    return new Promise(async (resolve) => {
      let done = false;
      const finish = (v) => { if (done) return; done = true; resolve(v); sh.close(); };
      const skip = new Set(exclude.map(x => String(x || '').toLowerCase()));
      const recent = await this._people().catch(() => []);
      const sh = this._sheet({ title, body: `<div class="searchbar g pk-search">${ICON.search}<input type="search" placeholder="Search" autocomplete="off" autocapitalize="off" enterkeyhint="search"></div><div class="pk-list"></div>` });
      sh.onClose = () => { if (!done) { done = true; resolve(null); } };
      const input = sh.el.querySelector('input'), list = sh.el.querySelector('.pk-list');
      let rows = [];
      const draw = () => {
        const q = input.value.trim().toLowerCase();
        const contacts = this._sortedContacts(q).filter(c => (c.emails || []).some(e => !skip.has(e.value)));
        const inBook = new Set(this._contactList().flatMap(c => (c.emails || []).map(e => e.value)));
        const others = recent.filter(p => !inBook.has(p.email) && !skip.has(p.email) && (!q || p.email.includes(q) || (p.name || '').toLowerCase().includes(q))).slice(0, q ? 20 : 12);
        rows = [];
        let html = '';
        if (contacts.length) {
          html += '<div class="sh">Contacts</div><div class="pk-group">';
          for (const c of contacts) {
            const emails = (c.emails || []).filter(e => !skip.has(e.value));
            rows.push({ name: contactName(c), emails });
            html += `<div class="ct-row" data-pk="${rows.length - 1}">${this._contactAv(c, 40)}<div style="min-width:0;flex:1"><div class="n">${esc(contactName(c) || emails[0].value)}</div><div class="s">${esc(emails.length > 1 ? `${emails.length} email addresses` : emails[0].value)}</div></div>${emails.length > 1 ? `<span class="pk-more">${ICON.chevR}</span>` : ''}</div>`;
          }
          html += '</div>';
        }
        if (others.length) {
          html += `<div class="sh">People You Email</div><div class="pk-group">`;
          for (const p of others) {
            rows.push({ name: p.name || '', emails: [{ value: p.email }] });
            html += `<div class="ct-row" data-pk="${rows.length - 1}">${this._avatar({ name: p.name || p.email, email: p.email }, 40)}<div style="min-width:0;flex:1"><div class="n">${esc(p.name || p.email)}</div>${p.name ? `<div class="s">${esc(p.email)}</div>` : ''}</div></div>`;
          }
          html += '</div>';
        }
        if (!html) {
          html = q && EMAIL_RE.test(q) ? `<div class="pk-group"><div class="ct-row" data-typed="1"><div style="min-width:0;flex:1"><div class="n">Use “${esc(q)}”</div></div></div></div>`
            : `<div class="empty"><b>${q ? 'No Results' : 'No Contacts'}</b>${q ? `No one matches “${esc(input.value.trim())}”.` : 'Add people in Contacts from the Mailboxes screen, and they’ll appear here.'}</div>`;
        }
        list.innerHTML = html;
      };
      input.addEventListener('input', draw);
      input.addEventListener('keydown', (e) => { if (e.key === 'Enter') { e.preventDefault(); const first = list.querySelector('[data-pk],[data-typed]'); first?.click(); } });
      list.addEventListener('click', async (e) => {
        const row = e.target.closest('[data-pk],[data-typed]');
        if (!row) return;
        if (row.dataset.typed) { finish(parseAddresses(input.value.trim())[0] || null); return; }
        const r = rows[+row.dataset.pk];
        if (r.emails.length === 1) { finish({ name: r.name, email: r.emails[0].value }); return; }
        const v = await this._menu(row, [{ header: r.name || 'Email' }, ...r.emails.map((x, i) => ({ text: x.value, value: String(i), icon: 'mail' }))], { align: 'left' });
        if (v !== null && v !== undefined && r.emails[+v]) finish({ name: r.name, email: r.emails[+v].value });
      });
      draw();
    });
  },

  // people you've emailed, to add in one go
  async _addRecentPeople() {
    const people = (await this._people()).filter(p => !this._contactByEmail(p.email));
    if (!people.length) { this._toast('Everyone you email is already a contact.'); return; }
    const picked = new Set();
    const sh = this._sheet({
      title: 'Add People You Email', action: 'Add',
      body: `<div class="sgroup">${people.slice(0, 80).map((p, i) => `<label class="gr"><span class="gl">${esc(p.name || p.email)}${p.name ? `<small style="text-transform:none">${esc(p.email)}</small>` : ''}</span><label class="tsw"><input type="checkbox" data-i="${i}"><span></span></label></label>`).join('')}</div>`,
      onAction: async () => {
        if (!picked.size) { this._toast('Choose at least one person.'); return false; }
        const list = [...picked].map(i => people[i]).map(p => {
          const [first, ...rest] = String(p.name || '').split(' ');
          return { first: p.name ? first : '', last: rest.join(' '), emails: [{ label: 'home', value: p.email }] };
        });
        await this._call('contacts/save', { contacts: list });
        this._toast(`${list.length} contact${list.length === 1 ? '' : 's'} added`);
        return true;
      },
    });
    sh.el.addEventListener('change', (e) => { const i = e.target.dataset?.i; if (i !== undefined) { if (e.target.checked) picked.add(+i); else picked.delete(+i); } });
  },

  _pg_contact({ cid }) {
    const el = this._el(`<div class="contactpg">
      <div class="top"><button class="cb g" data-a="back" aria-label="Back">${ICON.back}</button><div class="title"></div><div class="right"><button class="pill g" data-a="edit">Edit</button></div></div>
      <div class="scroll"><div class="body"></div></div></div>`);
    const body = el.querySelector('.body');
    const draw = () => {
      const c = this._contact(cid);
      if (!c) { body.innerHTML = '<div class="empty" style="padding-top:100px">This contact has been deleted.</div>'; return; }
      const name = contactName(c) || (c.emails || [])[0]?.value || 'No Name';
      const emails = c.emails || [], phones = c.phones || [], addrs = c.addresses || [];
      const vip = emails.some(e => this._isVip(e.value));
      body.innerHTML = `<div class="ct-head">${this._contactAv(c, 96)}<h2>${esc(name)}</h2>${c.company || c.job_title ? `<p>${esc([c.job_title, c.company].filter(Boolean).join(', '))}</p>` : ''}</div>
        <div class="ct-acts">
          <button data-a="mail"${emails.length ? '' : ' disabled'}>${ICON.mail}<span>Email</span></button>
          <button data-a="vip" class="${vip ? 'on' : ''}"${emails.length ? '' : ' disabled'}>${vip ? ICON.starF : ICON.star}<span>VIP</span></button>
          <button data-a="recent"${emails.length ? '' : ' disabled'}>${ICON.inbox}<span>Emails</span></button>
          <button data-a="call"${phones.length ? '' : ' disabled'}>${ICON.phone}<span>Call</span></button>
        </div>
        <div class="ct-body">
          ${emails.length ? `<div class="sgroup">${emails.map((x, i) => `<div class="gr" role="button" data-email="${i}"><span class="gl v"><small>${esc(x.label || 'email')}</small>${esc(x.value)}</span></div>`).join('')}</div>` : ''}
          ${phones.length ? `<div class="sgroup" style="margin-top:14px">${phones.map((x, i) => `<div class="gr" role="button" data-phone="${i}"><span class="gl v"><small>${esc(x.label || 'phone')}</small>${esc(x.value)}</span></div>`).join('')}</div>` : ''}
          ${addrs.length ? `<div class="sgroup" style="margin-top:14px">${addrs.map((x, i) => `<div class="gr" role="button" data-addr="${i}"><span class="gl v"><small>${esc(x.label || 'address')}</small>${esc(formatAddress(x))}</span></div>`).join('')}</div>` : ''}
          ${c.birthday ? `<div class="sgroup" style="margin-top:14px"><div class="gr"><span class="gl plain"><small>birthday</small>${esc(c.birthday)}</span></div></div>` : ''}
          ${c.notes ? `<div class="sgroup" style="margin-top:14px"><div class="gr"><span class="gl plain"><small>notes</small>${esc(c.notes)}</span></div></div>` : ''}
          <div class="sgroup" style="margin-top:22px">
            <div class="gr blue" role="button" data-a="share"><span class="gl">Share Contact</span></div>
            <div class="gr red" role="button" data-a="delete"><span class="gl">Delete Contact</span></div>
          </div>
        </div>`;
    };
    const pick = async (anchor, list, label) => {
      if (list.length === 1) return list[0];
      const v = await this._menu(anchor, list.map((x, i) => ({ text: `${x.label ? `${x.label}: ` : ''}${label ? formatAddress(x) : x.value}`, value: String(i) })));
      return v === null ? null : list[+v];
    };
    el.addEventListener('click', async (e) => {
      const c = this._contact(cid);
      const a = e.target.closest('[data-a]')?.dataset.a;
      if (a === 'back') { this._back(); return; }
      if (!c) return;
      const name = contactName(c);
      try {
        if (a === 'edit') { this._nav('contactEdit', { cid }); return; }
        if (a === 'mail') { const x = await pick(e.target.closest('button'), c.emails); if (x) this._compose({ to: [{ name, email: x.value }] }); return; }
        if (a === 'call') { const x = await pick(e.target.closest('button'), c.phones); if (x) openExternal(`tel:${telValue(x.value)}`); return; }
        if (a === 'vip') {
          const on = !(c.emails || []).some(x => this._isVip(x.value));
          for (const x of c.emails || []) await this._call('vip', { email: x.value, name, on });
          this._toast(on ? `${name || 'They'} ${name ? 'is' : 'are'} now a VIP` : 'Removed from VIP');
          return;
        }
        if (a === 'recent') { this._nav('list', { kind: 'inbox', search: (c.emails || [])[0].value }); return; }
        if (a === 'share') { this._exportContacts([c], `${(name || 'Contact').replace(/[^\w ]/g, '')}.vcf`); return; }
        if (a === 'delete') {
          if (!(await this._confirm('Delete Contact?', `${name || 'This contact'} will be deleted from your contacts.`, 'Delete', true))) return;
          await this._call('contacts/delete', { ids: [cid] });
          this._back();
          return;
        }
      } catch (err) { this._err(err); return; }
      const em = e.target.closest('[data-email]')?.dataset.email;
      if (em !== undefined) { this._compose({ to: [{ name, email: c.emails[+em].value }] }); return; }
      const ph = e.target.closest('[data-phone]')?.dataset.phone;
      if (ph !== undefined) { openExternal(`tel:${telValue(c.phones[+ph].value)}`); return; }
      const ad = e.target.closest('[data-addr]')?.dataset.addr;
      if (ad !== undefined) openExternal(mapsUrl(c.addresses[+ad]));
    });
    return { el, refresh: (what) => { if (['all', 'contacts', 'vips', 'back'].includes(what)) draw(); } };
  },

  _pg_contactEdit({ cid, prefill }) {
    const old = cid ? this._contact(cid) : null;
    const c = JSON.parse(JSON.stringify(old || { ...(prefill || {}) }));
    c.emails = c.emails || []; c.phones = c.phones || []; c.addresses = c.addresses || [];
    if (!c.emails.length) c.emails.push({ label: 'home', value: '' });
    const el = this._el(`<div class="editpg">
      <div class="top"><button class="pill g" data-a="cancel">Cancel</button><div class="title always">${old ? 'Edit Contact' : 'New Contact'}</div><div class="right"><button class="pill g accent" data-a="save">Done</button></div></div>
      <div class="scroll"><div class="ce-edit"></div></div><input type="file" accept="image/*" hidden></div>`);
    const box = el.querySelector('.ce-edit'), fileIn = el.querySelector('input[type=file]');
    const field = (k, ph) => `<div class="gr"><input class="gin left" data-k="${k}" value="${esc(c[k] || '')}" placeholder="${esc(ph)}" autocapitalize="words"></div>`;
    const list = (kind, labels, ph, type) => `<div class="sgroup" style="margin-top:14px">${c[kind].map((x, i) => `<div class="gr lrow"><button class="rm" data-rm="${kind}:${i}" aria-label="Remove">${ICON.x}</button>
      <select class="gsel" data-l="${kind}:${i}">${[...new Set([...labels, x.label].filter(Boolean))].map(l => `<option${l === x.label ? ' selected' : ''}>${esc(l)}</option>`).join('')}</select>
      <input class="gin" type="${type}" data-v="${kind}:${i}" value="${esc(x.value || '')}" placeholder="${esc(ph)}" autocapitalize="off"></div>`).join('')}
      <div class="gr" role="button" data-add="${kind}"><span class="add"><span>${ICON.plus}</span>add ${kind === 'emails' ? 'email' : 'phone'}</span></div></div>`;
    const draw = () => {
      box.innerHTML = `<div class="photo">${c.photo ? `<div class="av" style="width:96px;height:96px"><img src="${esc(c.photo)}" alt=""></div>` : this._avatar({ name: contactName(c) || '?', email: c.emails[0]?.value }, 96)}<button data-a="photo">${c.photo ? 'Change Photo' : 'Add Photo'}</button>${c.photo ? '<button data-a="nophoto" style="color:var(--ce-red)">Remove Photo</button>' : ''}</div>
        <div class="sgroup">${field('first', 'First name')}${field('last', 'Last name')}${field('company', 'Company')}${field('job_title', 'Job title')}</div>
        ${list('emails', EMAIL_LABELS, 'Email', 'email')}
        ${list('phones', PHONE_LABELS, 'Phone', 'tel')}
        <div class="sgroup" style="margin-top:14px"><div class="gr"><span class="gl" style="flex:0 0 90px">Birthday</span><input class="gin" type="date" data-k="birthday" value="${esc(normDate(c.birthday || '') || '')}"></div></div>
        <div class="sgroup" style="margin-top:14px"><textarea class="gta" data-k="notes" placeholder="Notes">${esc(c.notes || '')}</textarea></div>
        ${old ? '<div class="sgroup" style="margin-top:22px"><div class="gr red center" role="button" data-a="delete"><span class="gl">Delete Contact</span></div></div>' : ''}`;
    };
    const read = () => {
      box.querySelectorAll('[data-k]').forEach(i => { c[i.dataset.k] = i.value.trim(); });
      box.querySelectorAll('[data-v]').forEach(i => { const [k, n] = i.dataset.v.split(':'); c[k][+n].value = i.value.trim(); });
      box.querySelectorAll('[data-l]').forEach(i => { const [k, n] = i.dataset.l.split(':'); c[k][+n].label = i.value; });
    };
    draw();
    fileIn.addEventListener('change', async () => { const f = fileIn.files[0]; fileIn.value = ''; if (!f) return; read(); try { c.photo = await fileToAvatar(f, 320); draw(); } catch (e) { this._toast('Couldn’t use that picture.'); } });
    el.addEventListener('click', async (e) => {
      const a = e.target.closest('[data-a]')?.dataset.a;
      if (a === 'cancel') { this._back(); return; }
      if (a === 'photo') { fileIn.click(); return; }
      if (a === 'nophoto') { read(); delete c.photo; draw(); return; }
      if (a === 'delete') {
        if (!(await this._confirm('Delete Contact?', '', 'Delete', true))) return;
        try { await this._call('contacts/delete', { ids: [cid] }); this._back(false); this._back(); } catch (err) { this._err(err); }
        return;
      }
      if (a === 'save') {
        read();
        c.emails = c.emails.filter(x => x.value);
        c.phones = c.phones.filter(x => x.value);
        const bad = c.emails.find(x => !EMAIL_RE.test(x.value));
        if (bad) { this._toast(`${bad.value} isn’t a valid email address.`); return; }
        if (!contactName(c) && !c.emails.length && !c.phones.length) { this._toast('Add a name or an email address.'); return; }
        try { await this._call('contacts/save', { contacts: [{ ...c, id: cid || undefined }] }); this._back(); } catch (err) { this._err(err); }
        return;
      }
      const rm = e.target.closest('[data-rm]')?.dataset.rm;
      if (rm) { read(); const [k, n] = rm.split(':'); c[k].splice(+n, 1); draw(); return; }
      const add = e.target.closest('[data-add]')?.dataset.add;
      if (add) { read(); c[add].push({ label: add === 'emails' ? 'home' : 'mobile', value: '' }); draw(); box.querySelector(`[data-v="${add}:${c[add].length - 1}"]`)?.focus(); }
    });
    return { el };
  },

  async _importVCards(file) {
    try {
      const text = await file.text();
      const cards = parseVCards(text);
      if (!cards.length) { this._toast('No contacts were found in that file.'); return; }
      for (let i = 0; i < cards.length; i += 200) await this._call('contacts/save', { contacts: cards.slice(i, i + 200) });
      this._toast(`${cards.length} contact${cards.length === 1 ? '' : 's'} imported`);
    } catch (err) { this._err(err); }
  },

  _exportContacts(list, filename) {
    const blob = new Blob([list.map(contactToVCard).join('\r\n')], { type: 'text/vcard' });
    const url = URL.createObjectURL(blob);
    this._download(url, filename);
    setTimeout(() => URL.revokeObjectURL(url), 30000);
  },
});
