// Undo Send, place, invitation and the rest live in each new email
function ceZoneName(hass, id) {
  if (id === 'zone.home') return 'Home';
  return hass?.states?.[id]?.attributes?.friendly_name || String(id).replace(/^zone\./, '').replace(/_/g, ' ');
}

function ceDataUrl(blob) {
  return new Promise((res, rej) => { const r = new FileReader(); r.onload = () => res(r.result); r.onerror = rej; r.readAsDataURL(blob); });
}

function ceLoadImage(src, cors = false) {
  return new Promise((res, rej) => {
    const im = new Image();
    if (cors) im.crossOrigin = 'anonymous';
    im.onload = () => res(im); im.onerror = rej; im.src = src;
  });
}

// a picture made smaller (cameras can be several megabytes), as a JPEG data link
async function ceShrink(blob, max = 1280, q = 0.85) {
  const url = URL.createObjectURL(blob);
  try {
    const im = await ceLoadImage(url);
    const sc = Math.min(1, max / Math.max(im.naturalWidth, im.naturalHeight));
    const c = document.createElement('canvas');
    c.width = Math.round(im.naturalWidth * sc); c.height = Math.round(im.naturalHeight * sc);
    c.getContext('2d').drawImage(im, 0, 0, c.width, c.height);
    return c.toDataURL('image/jpeg', q);
  } finally { URL.revokeObjectURL(url); }
}

function ceWhen(inv, hass) {
  if (!inv?.start) return '';
  const allDay = inv.all_day || /^\d{4}-\d{2}-\d{2}$/.test(inv.start);
  const s = new Date(allDay ? `${inv.start}T00:00` : inv.start);
  const day = (d) => d.toLocaleDateString(locale(hass), { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' });
  if (allDay) return `${day(s)} (all day)`;
  const e = inv.end ? new Date(inv.end) : null;
  return `${day(s)}, ${fmtTime(s.getTime(), hass)}${e ? ` to ${sameDay(s, e) ? fmtTime(e.getTime(), hass) : `${day(e)}, ${fmtTime(e.getTime(), hass)}`}` : ''}`;
}

const _ceApplyTheme = CrowMessengerEmail.prototype._applyTheme;
const _ceOnEvent = CrowMessengerEmail.prototype._onEvent;
const _cePgReader = CrowMessengerEmail.prototype._pg_reader;
const _cePgCompose = CrowMessengerEmail.prototype._pg_compose;
const _ceSigHtml = CrowMessengerEmail.prototype._sigHtml;

Object.assign(CrowMessengerEmail.prototype, {
  // ── colours and glass ────────────────────────────────────────────────
  _applyTheme() {
    _ceApplyTheme.call(this);
    const p = this._s?.prefs || {};
    if (p.accent && !this._skinned?.()) this.style.setProperty('--ce-accent', p.accent); else this.style.removeProperty('--ce-accent');
    // Glass: from clear (0) to frosted (100)
    const f = this._config?.glass_frost;
    if (f === undefined || f === null || f === '' || this.getAttribute('data-style') !== 'glass') {
      this.removeAttribute('data-frost');
      ['--ce-glass', '--ce-blur', '--ce-card-blur', '--ce-card-tint'].forEach(v => this.style.removeProperty(v));
      return;
    }
    const v = clamp(Number(f) || 0, 0, 100) / 100;
    const dark = this._isDark();
    this.setAttribute('data-frost', '');
    this.style.setProperty('--ce-glass', dark ? `rgba(56,56,60,${(0.12 + v * 0.8).toFixed(2)})` : `rgba(255,255,255,${(0.12 + v * 0.8).toFixed(2)})`);
    this.style.setProperty('--ce-blur', `${Math.round(2 + v * 34)}px`);
    this.style.setProperty('--ce-card-blur', `${Math.round(v * 48)}px`);
    this.style.setProperty('--ce-card-tint', `${Math.round(12 + v * 76)}%`);
  },
  _skinned() { return this._skin?.().id && this._skin().id !== 'iphone'; },

  // an account's own colour as the accent, while reading or writing its email
  _accountAccent(el, accountId) {
    if (!this._s.prefs?.account_accents || !el) return;
    const a = this._acc(accountId);
    if (a?.color) el.style.setProperty('--ce-accent', a.color); else el.style.removeProperty('--ce-accent');
  },

  _onEvent(ev) {
    const s = this._s;
    if (ev.type === 'state') {
      s.pins = ev.pins || [];
      s.person = ev.person || null;
      s.emailHa = !!ev.email_ha;
      _ceOnEvent.call(this, ev);
      if (!ev.cached) this._loadPins();
      return;
    }
    switch (ev.type) {
      case 'pins': s.pins = ev.pins || []; this._loadPins(); return;
      case 'poll': this._refresh('poll', ev); return;
      case 'email_ha': s.emailHa = !!ev.email_ha; return;
      default: _ceOnEvent.call(this, ev);
    }
  },

  // ── pinned emails ────────────────────────────────────────────────────
  async _loadPins() {
    if (!(this._s.pins || []).length) { this._s.pinItems = []; this._refresh('pins'); return; }
    try { this._s.pinItems = await this._call('pins'); } catch (e) { /* keep what was there */ }
    this._refresh('pins');
  },
  _isPinned(it) { return (this._s.pins || []).some(p => p.account === it.account && p.folder === it.folder && p.uid === it.uid); },
  async _setPin(it, on, messageId = '') {
    try {
      this._s.pins = await this._call('pins/set', { account: it.account, folder: it.folder, uid: it.uid, on, message_id: messageId || '' });
      this._toast(on ? 'Pinned to the top of the Inbox' : 'Unpinned');
      this._loadPins();
    } catch (err) { this._err(err); }
  },
  // the pinned emails at the top of an Inbox; the keys shown, so the list below leaves them out
  _drawPinned(box, { combined, account, show }) {
    if (!box) return new Set();
    const items = !show ? [] : (this._s.pinItems || []).filter(i => combined || i.account === account);
    if (!items.length) { box.innerHTML = ''; return new Set(); }
    box.innerHTML = `<div class="phead">${ICON.pushpinF}Pinned</div><div class="plist">${items.map((it, i) => this._rowHtml(it, { showAcct: combined && this._multi(), index: i })).join('')}</div>`;
    if (!box._wired) {
      box._wired = true;
      box.addEventListener('click', (e) => {
        e.stopPropagation();
        const key = e.target.closest('.erow')?.dataset.key;
        const it = (this._s.pinItems || []).find(x => this._itemKey(x) === key);
        if (!it) return;
        it.seen = true;
        this._nav('reader', { account: it.account, folder: it.folder, uid: it.uid, siblings: () => this._s.pinItems || [] });
      });
    }
    return new Set(items.map(i => this._itemKey(i)));
  },

  // ── My Card: a signature with your name, photo and details ───────────
  _sigHtml(acc) {
    const c = acc?.sig_card;
    if (!c?.on) return _ceSigHtml.call(this, acc);
    const name = c.name || acc.from_name || '';
    const lines = [c.title, c.phone ? `<a href="tel:${esc(String(c.phone).replace(/[^\d+]/g, ''))}" style="color:inherit">${esc(c.phone)}</a>` : '', `<a href="mailto:${esc(acc.email)}" style="color:inherit">${esc(acc.email)}</a>`,
      c.web ? `<a href="${esc(/^https?:/i.test(c.web) ? c.web : `https://${c.web}`)}" style="color:inherit">${esc(c.web.replace(/^https?:\/\//i, ''))}</a>` : ''].filter(Boolean);
    const text = (acc.signature || '').trim();
    return `<div class="sig">${text ? `${textToHtml(text).replace(/^<p>|<\/p>$/g, '')}<br><br>` : ''}<table cellpadding="0" cellspacing="0" style="border-collapse:collapse;font-family:-apple-system,Helvetica,Arial,sans-serif"><tr>`
      + (c.photo ? `<td style="padding-right:12px;vertical-align:middle"><img src="${esc(c.photo)}" width="64" height="64" alt="${esc(name)}" style="width:64px;height:64px;border-radius:32px;object-fit:cover;display:block"></td>` : '')
      + `<td style="vertical-align:middle;font-size:13px;line-height:1.45;color:#6b6b70"><div style="font-size:15px;font-weight:700;color:#1c1c1e">${esc(name)}</div>${lines.join('<br>')}</td></tr></table></div>`;
  },

  _pg_mycard(data) {
    const a = this._acc(data.account);
    const c = { on: false, name: a?.from_name || '', title: '', phone: '', web: '', photo: '', ...(a?.sig_card || {}) };
    const el = this._simplePage('My Card', '<div class="body"></div>');
    this._scrollTitle(el);
    const body = el.querySelector('.body');
    const save = async () => {
      try {
        const saved = await this._call('account/save', { account: { id: a.id, sig_card: c } });
        const i = this._s.accounts.findIndex(x => x.id === saved.id);
        if (i >= 0) this._s.accounts[i] = saved;
      } catch (err) { this._err(err); }
    };
    const draw = () => {
      body.innerHTML = `<div class="sgroup">
          <div class="gr"><span class="gl">Add My Card to Emails<small>Your name, photo and details under your signature, in each new email from ${esc(a?.email || '')}.</small></span>${this._sw('f-on', c.on)}</div></div>
        <div class="sh">Preview</div><div class="sgroup"><div class="mycard-prev">${c.photo ? `<img src="${esc(c.photo)}" alt="">` : `<span class="ph">${ICON.user}</span>`}
          <div style="min-width:0"><b>${esc(c.name || 'Your Name')}</b><div style="color:var(--ce-text2);font-size:13px">${esc([c.title, c.phone, a?.email].filter(Boolean).join(' · '))}</div></div></div>
          <div class="gr blue" role="button" data-a="photo"><span class="gl">${c.photo ? 'Change Photo' : 'Add Photo'}</span></div>
          ${c.photo ? '<div class="gr red" role="button" data-a="nophoto"><span class="gl">Remove Photo</span></div>' : ''}</div>
        <div class="sh">Details</div><div class="sgroup xform">
          ${this.host ? '<div class="gr blue" role="button" data-a="fromcard"><span class="gl">Fill In from My Card in Contacts</span></div>' : ''}
          <div class="gr"><span class="gl" style="flex:0 0 100px">Name</span><input class="gin" data-k="name" value="${esc(c.name)}" placeholder="Your Name"></div>
          <div class="gr"><span class="gl" style="flex:0 0 100px">Job Title</span><input class="gin" data-k="title" value="${esc(c.title)}" placeholder="Optional"></div>
          <div class="gr"><span class="gl" style="flex:0 0 100px">Phone</span><input class="gin" data-k="phone" type="tel" value="${esc(c.phone)}" placeholder="Optional"></div>
          <div class="gr"><span class="gl" style="flex:0 0 100px">Website</span><input class="gin" data-k="web" value="${esc(c.web)}" placeholder="Optional" autocapitalize="off"></div></div>
        <div class="sfoot">Your signature text still goes above My Card. The photo is small, and is sent inside each email.</div>
        <input type="file" accept="image/*" hidden>`;
    };
    draw();
    el.addEventListener('change', async (e) => {
      const t = e.target;
      if (t.classList.contains('f-on')) { c.on = t.checked; save(); return; }
      if (t.dataset.k) { c[t.dataset.k] = t.value.trim(); save(); draw(); return; }
      if (t.type === 'file' && t.files[0]) {
        try { c.photo = await ceShrink(t.files[0], 192, 0.82); await save(); draw(); } catch (err) { this._toast('Couldn’t use that picture.'); }
      }
    });
    el.addEventListener('click', (e) => {
      const k = e.target.closest('[data-a]')?.dataset.a;
      if (k === 'back') this._back();
      if (k === 'photo') body.querySelector('input[type=file]').click();
      if (k === 'nophoto') { c.photo = ''; save(); draw(); }
      if (k === 'fromcard') this._fillFromMyCard(c).then(ok => { if (ok) { save(); draw(); } });
    });
    return { el, refresh: (what) => { if (what === 'accounts') { Object.assign(c, this._acc(data.account)?.sig_card || {}); } } };
  },

  // ── Sketch ───────────────────────────────────────────────────────────
  _openSketch() {
    return new Promise((resolve) => {
      const W = 1000, H = 700;
      const el = this._el(`<div class="sketch">
        <div class="skt"><button class="pill" data-k="cancel">Cancel</button><b>Sketch</b><button class="pill accent" data-k="done">Add</button></div>
        <div class="skc"><canvas width="${W}" height="${H}"></canvas></div>
        <div class="skb">
          ${SKETCH_COLOURS.map((c, i) => `<button class="sw${i === 0 ? ' on' : ''}" data-col="${c}" style="background:${c}" aria-label="Colour"></button>`).join('')}
          <span class="brk"></span>
          ${SKETCH_SIZES.map((z, i) => `<button class="sz${i === 1 ? ' on' : ''}" data-size="${z}" aria-label="Size"><i style="width:${4 + i * 5}px;height:${4 + i * 5}px"></i></button>`).join('')}
          <span class="vsep"></span>
          <button class="cb" data-k="undo" aria-label="Undo">${ICON.undo}</button>
          <button class="cb" data-k="clear" aria-label="Clear">${ICON.eraser}</button>
        </div></div>`);
      this._root.appendChild(el);
      const cv = el.querySelector('canvas'), ctx = cv.getContext('2d'), wrap = el.querySelector('.skc');
      const fit = () => { const r = wrap.getBoundingClientRect(); const sc = Math.min((r.width - 24) / W, (r.height - 8) / H); cv.style.width = `${Math.floor(W * sc)}px`; cv.style.height = `${Math.floor(H * sc)}px`; };
      requestAnimationFrame(fit);
      let colour = SKETCH_COLOURS[0], size = SKETCH_SIZES[1], cur = null;
      const strokes = [];
      const redraw = () => {
        ctx.fillStyle = '#fff'; ctx.fillRect(0, 0, W, H);
        for (const s of strokes) {
          ctx.strokeStyle = s.c; ctx.fillStyle = s.c; ctx.lineWidth = s.w; ctx.lineCap = 'round'; ctx.lineJoin = 'round';
          if (s.p.length === 1) { ctx.beginPath(); ctx.arc(s.p[0][0], s.p[0][1], s.w / 2, 0, Math.PI * 2); ctx.fill(); continue; }
          ctx.beginPath(); ctx.moveTo(s.p[0][0], s.p[0][1]);
          for (let i = 1; i < s.p.length - 1; i++) ctx.quadraticCurveTo(s.p[i][0], s.p[i][1], (s.p[i][0] + s.p[i + 1][0]) / 2, (s.p[i][1] + s.p[i + 1][1]) / 2);
          const last = s.p[s.p.length - 1]; ctx.lineTo(last[0], last[1]); ctx.stroke();
        }
      };
      redraw();
      const pt = (e) => { const r = cv.getBoundingClientRect(); const k = W / r.width; return [(e.clientX - r.left) * k, (e.clientY - r.top) * k]; };
      cv.addEventListener('pointerdown', (e) => { cv.setPointerCapture(e.pointerId); cur = { c: colour, w: size * 2, p: [pt(e)] }; strokes.push(cur); redraw(); });
      cv.addEventListener('pointermove', (e) => { if (cur) { cur.p.push(pt(e)); redraw(); } });
      const end = () => { cur = null; };
      cv.addEventListener('pointerup', end); cv.addEventListener('pointercancel', end);
      el.addEventListener('click', (e) => {
        const col = e.target.closest('[data-col]');
        if (col) { colour = col.dataset.col; el.querySelectorAll('.sw').forEach(b => b.classList.toggle('on', b === col)); return; }
        const sz = e.target.closest('[data-size]');
        if (sz) { size = +sz.dataset.size; el.querySelectorAll('.sz').forEach(b => b.classList.toggle('on', b === sz)); return; }
        const k = e.target.closest('[data-k]')?.dataset.k;
        if (k === 'undo') { strokes.pop(); redraw(); }
        if (k === 'clear') { strokes.length = 0; redraw(); }
        if (k === 'cancel') { el.remove(); resolve(null); }
        if (k === 'done') { el.remove(); resolve(strokes.length ? cv.toDataURL('image/png') : null); }
      });
    });
  },

  // ── a list to choose from, with a search box ─────────────────────────
  _pickFrom({ title, items, empty = 'Nothing to choose from.', search = true }) {
    return new Promise((resolve) => {
      let done = false;
      const sh = this._sheet({ title, body: `${search ? `<div class="searchbar g pk-search">${ICON.search}<input type="search" placeholder="Search" autocomplete="off"></div>` : ''}<div class="sgroup xpick"></div>` });
      sh.onClose = () => { if (!done) resolve(null); };
      const box = sh.el.querySelector('.xpick'), inp = sh.el.querySelector('input');
      let shown = items;
      const draw = () => {
        const q = (inp?.value || '').trim().toLowerCase();
        shown = q ? items.filter(i => `${i.text} ${i.sub || ''}`.toLowerCase().includes(q)) : items;
        box.innerHTML = shown.length ? shown.slice(0, 200).map((i, n) => `<div class="gr${i.icon ? ' icon-row' : ''}" role="button" data-n="${n}">${i.icon ? `<span class="gi" style="background:${i.colour || 'var(--ce-accent)'}">${ICON[i.icon] || ''}</span>` : ''}<span class="gl">${esc(i.text)}${i.sub ? `<small>${esc(i.sub)}</small>` : ''}</span>${i.value2 ? `<span class="gv">${esc(i.value2)}</span>` : ''}</div>`).join('')
          : `<div class="gr"><span class="gl" style="color:var(--ce-text2)">${esc(empty)}</span></div>`;
      };
      draw();
      inp?.addEventListener('input', draw);
      box.addEventListener('click', (e) => { const n = e.target.closest('[data-n]')?.dataset.n; if (n !== undefined) { done = true; resolve(shown[+n]); sh.close(); } });
    });
  },
  _stateName(id) { return this._hass.states[id]?.attributes?.friendly_name || id; },
  _stateText(id) {
    const st = this._hass.states[id];
    if (!st) return '';
    try { if (this._hass.formatEntityState) return this._hass.formatEntityState(st); } catch (e) { /* older Home Assistant */ }
    const u = st.attributes?.unit_of_measurement;
    return `${st.state}${u ? ` ${u}` : ''}`;
  },

  // ── Insert menu in a new email ───────────────────────────────────────
  _insertItems(ctx) {
    const st = ctx.st, h = this._hass;
    const has = (d) => Object.keys(h.states).some(id => id.startsWith(`${d}.`));
    return [
      { text: 'Sketch', value: 'sketch', icon: 'sketch' },
      { text: 'Contact Card', value: 'vcard', icon: 'card' },
      { text: 'My Location', value: 'location', icon: 'pin' },
      { sep: true },
      { text: 'From Home Assistant', value: 'ha', icon: 'house', sub: [
        ...(has('camera') ? [{ text: 'Camera Snapshot', value: 'camera', icon: 'camera' }] : []),
        { text: 'Home Status', value: 'status', icon: 'house' },
        { text: 'Sensor Reading', value: 'sensor', icon: 'gauge' },
      ] },
      { text: 'Event Invitation', value: 'invite', icon: 'calendar' },
      { text: 'Voting Buttons', value: 'poll', icon: 'poll' },
      { text: 'Checklist', value: 'checklist', icon: 'checklist' },
      { sep: true },
      { text: 'Ask for a Read Receipt', value: 'receipt', checked: !!st.readReceipt },
    ];
  },

  async _doInsert(v, ctx) {
    const { st, insertAt, range, upload, drawExtras } = ctx;
    try {
      if (v === 'sketch') {
        const url = await this._openSketch();
        if (url) insertAt(range, `<img src="${url}" alt="Sketch" style="max-width:100%;height:auto;border-radius:8px" width="500">&nbsp;`);
      } else if (v === 'vcard') {
        const cs = this._sortedContacts ? this._sortedContacts('') : this._contactList();
        if (!cs.length) { this._toast('Add people in Contacts first.'); return; }
        const pick = await this._pickFrom({ title: 'Send a Contact', items: cs.map(c => ({ text: contactName(c), sub: c.emails?.[0]?.value || c.phones?.[0]?.value || c.company || '', c })) });
        if (!pick) return;
        const name = (contactName(pick.c) || 'Contact').replace(/[^\w ,.-]/g, '').trim() || 'Contact';
        await upload(new File([contactToVCard(pick.c)], `${name}.vcf`, { type: 'text/vcard' }));
      } else if (v === 'location') {
        this._toast('Finding where you are…');
        const loc = await this._myLocation();
        if (!loc) { this._toast('Couldn’t find your location. Check that the Companion app or browser can share it.'); return; }
        insertAt(range, await this._locationHtml(loc));
      } else if (v === 'camera') {
        const cams = Object.keys(this._hass.states).filter(id => id.startsWith('camera.')).map(id => ({ text: this._stateName(id), sub: id, id, icon: 'camera' }));
        const cam = await this._pickFrom({ title: 'Camera Snapshot', items: cams, search: cams.length > 6 });
        if (!cam) return;
        this._toast('Taking a snapshot…');
        const r = await this._hass.fetchWithAuth(`/api/camera_proxy/${cam.id}?t=${Date.now()}`);
        if (!r.ok) throw new Error('The camera didn’t send a picture.');
        const url = await ceShrink(await r.blob(), 1280, 0.82);
        insertAt(range, `<div><img src="${url}" alt="${esc(cam.text)}" style="max-width:100%;height:auto;border-radius:8px" width="640"><br><small style="color:#8e8e93">${esc(cam.text)}, ${esc(fmtFull(Date.now(), this._hass))}</small></div><div><br></div>`);
      } else if (v === 'status') {
        insertAt(range, this._homeStatusHtml());
      } else if (v === 'sensor') {
        const doms = ['sensor', 'binary_sensor', 'climate', 'weather', 'lock', 'cover', 'light', 'switch', 'alarm_control_panel', 'person', 'device_tracker', 'input_number', 'input_boolean', 'water_heater', 'vacuum', 'media_player'];
        const ids = Object.keys(this._hass.states).filter(id => doms.includes(id.split('.')[0])).sort((a, b) => this._stateName(a).localeCompare(this._stateName(b)));
        const pick = await this._pickFrom({ title: 'Sensor Reading', items: ids.map(id => ({ text: this._stateName(id), sub: id, value2: this._stateText(id), id })) });
        if (!pick) return;
        insertAt(range, `<b>${esc(pick.text)}:</b> ${esc(this._stateText(pick.id))} <small style="color:#8e8e93">(${esc(fmtTime(Date.now(), this._hass))})</small>&nbsp;`);
      } else if (v === 'invite') {
        const inv = await this._inviteSheet(st.invite);
        if (inv) { st.invite = inv; if (!ctx.subj.value.trim()) { ctx.subj.value = inv.title; ctx.subj.dispatchEvent(new Event('input')); } }
      } else if (v === 'poll') {
        const p = await this._pollSheet(st.poll, ctx.subj.value.trim());
        if (p) st.poll = p;
      } else if (v === 'checklist') {
        const html = await this._checklistHtml();
        if (html) insertAt(range, html);
      } else if (v === 'receipt') {
        st.readReceipt = !st.readReceipt;
        this._toast(st.readReceipt ? 'A read receipt will be asked for' : 'No read receipt');
      }
      st.changed = true;
      drawExtras();
    } catch (err) { this._err(err); }
  },

  // where you are: your person in Home Assistant (from the Companion app), or this device
  async _myLocation() {
    const h = this._hass;
    const mine = Object.values(h.states).find(s => s.entity_id.startsWith('person.') && s.attributes?.user_id === h.user?.id);
    const a = mine?.attributes || {};
    if (Number.isFinite(a.latitude) && Number.isFinite(a.longitude)) {
      const zone = mine.state && !['not_home', 'unknown', 'unavailable'].includes(mine.state) ? (mine.state === 'home' ? 'Home' : mine.state) : '';
      return { lat: a.latitude, lon: a.longitude, label: zone };
    }
    if (!navigator.geolocation) return null;
    return new Promise((res) => navigator.geolocation.getCurrentPosition(
      p => res({ lat: p.coords.latitude, lon: p.coords.longitude, label: '' }), () => res(null), { timeout: 12000, maximumAge: 60000 }));
  },

  // a little map (OpenStreetMap) with a pin, and links to open it in a maps app
  async _locationHtml({ lat, lon, label }) {
    const ll = `${lat.toFixed(6)},${lon.toFixed(6)}`;
    const links = [`<a href="https://maps.apple.com/?ll=${ll}&q=${encodeURIComponent(label || 'Shared Location')}">Apple Maps</a>`,
      `<a href="https://www.google.com/maps/search/?api=1&query=${ll}">Google Maps</a>`,
      `<a href="https://www.openstreetmap.org/?mlat=${lat.toFixed(6)}&mlon=${lon.toFixed(6)}#map=16/${ll.replace(',', '/')}">OpenStreetMap</a>`];
    let img = '';
    try {
      const z = 16, W = 600, H = 300;
      const n = 2 ** z;
      const x = (lon + 180) / 360 * n;
      const y = (1 - Math.log(Math.tan(lat * Math.PI / 180) + 1 / Math.cos(lat * Math.PI / 180)) / Math.PI) / 2 * n;
      const px = x * 256 - W / 2, py = y * 256 - H / 2;
      const c = document.createElement('canvas'); c.width = W; c.height = H;
      const g = c.getContext('2d');
      const tiles = [];
      for (let tx = Math.floor(px / 256); tx <= Math.floor((px + W) / 256); tx++) {
        for (let ty = Math.floor(py / 256); ty <= Math.floor((py + H) / 256); ty++) {
          tiles.push(ceLoadImage(`https://tile.openstreetmap.org/${z}/${((tx % n) + n) % n}/${ty}.png`, true).then(im => g.drawImage(im, tx * 256 - px, ty * 256 - py)));
        }
      }
      await Promise.all(tiles);
      // the pin
      g.fillStyle = '#FF3B30'; g.strokeStyle = '#fff'; g.lineWidth = 3;
      g.beginPath(); g.arc(W / 2, H / 2 - 18, 12, Math.PI * 0.85, Math.PI * 2.15); g.lineTo(W / 2, H / 2); g.closePath(); g.fill(); g.stroke();
      g.fillStyle = '#fff'; g.beginPath(); g.arc(W / 2, H / 2 - 18, 4.5, 0, Math.PI * 2); g.fill();
      g.fillStyle = 'rgba(255,255,255,0.8)'; g.fillRect(W - 150, H - 16, 150, 16);
      g.fillStyle = '#333'; g.font = '10px sans-serif'; g.fillText('© OpenStreetMap contributors', W - 146, H - 4);
      img = `<a href="https://maps.apple.com/?ll=${ll}"><img src="${c.toDataURL('image/jpeg', 0.85)}" alt="Map" width="300" style="max-width:100%;height:auto;border-radius:10px;display:block"></a>`;
    } catch (e) { /* no map picture: the links are enough */ }
    return `<div style="margin:6px 0">${img}<div style="margin-top:6px"><b>${esc(label ? `My Location: ${label}` : 'My Location')}</b><br><small>${links.join(' · ')}</small></div></div><div><br></div>`;
  },

  // a short summary of the house, for an email
  _homeStatusHtml() {
    const h = this._hass, S = Object.values(h.states);
    const name = (s) => s.attributes?.friendly_name || s.entity_id;
    const rows = [];
    const people = S.filter(s => s.entity_id.startsWith('person.'));
    if (people.length) rows.push(['People', people.map(p => `${name(p)}: ${p.state === 'home' ? 'Home' : p.state === 'not_home' ? 'Away' : p.state}`).join(', ')]);
    const alarm = S.find(s => s.entity_id.startsWith('alarm_control_panel.'));
    if (alarm) rows.push(['Alarm', this._stateText(alarm.entity_id)]);
    const locks = S.filter(s => s.entity_id.startsWith('lock.'));
    if (locks.length) { const open = locks.filter(l => l.state !== 'locked'); rows.push(['Locks', open.length ? `Unlocked: ${open.map(name).join(', ')}` : 'All locked']); }
    const openings = S.filter(s => s.entity_id.startsWith('binary_sensor.') && ['door', 'window', 'garage_door', 'opening'].includes(s.attributes?.device_class));
    if (openings.length) { const open = openings.filter(o => o.state === 'on'); rows.push(['Doors and Windows', open.length ? `Open: ${open.map(name).join(', ')}` : 'All closed']); }
    const covers = S.filter(s => s.entity_id.startsWith('cover.') && s.attributes?.device_class === 'garage');
    covers.forEach(c => rows.push([name(c), this._stateText(c.entity_id)]));
    const lights = S.filter(s => s.entity_id.startsWith('light.') && !s.attributes?.entity_id);
    if (lights.length) { const on = lights.filter(l => l.state === 'on'); rows.push(['Lights', on.length ? `${on.length} on: ${on.slice(0, 8).map(name).join(', ')}${on.length > 8 ? '…' : ''}` : 'All off']); }
    S.filter(s => s.entity_id.startsWith('climate.')).slice(0, 6).forEach(c => rows.push([name(c), `${c.attributes?.current_temperature ?? '—'}° (${this._stateText(c.entity_id)}${c.attributes?.temperature ? `, set to ${c.attributes.temperature}°` : ''})`]));
    const w = S.find(s => s.entity_id.startsWith('weather.'));
    if (w) rows.push(['Weather', `${this._stateText(w.entity_id)}, ${w.attributes?.temperature ?? ''}${w.attributes?.temperature_unit || '°'}`]);
    return `<table cellpadding="0" cellspacing="0" style="border-collapse:collapse;margin:6px 0;font-size:14px;min-width:260px">`
      + `<tr><td colspan="2" style="padding:0 0 6px;font-weight:700;font-size:16px">Home Status <span style="font-weight:400;color:#8e8e93;font-size:13px">${esc(fmtFull(Date.now(), h))}</span></td></tr>`
      + rows.map(([k, v]) => `<tr><td style="padding:5px 14px 5px 0;color:#8e8e93;vertical-align:top;border-top:1px solid #e5e5ea;white-space:nowrap">${esc(k)}</td><td style="padding:5px 0;border-top:1px solid #e5e5ea">${esc(v)}</td></tr>`).join('')
      + '</table><div><br></div>';
  },

  async _checklistHtml() {
    const lists = Object.keys(this._hass.states).filter(id => id.startsWith('todo.'));
    let items = ['', '', ''];
    const v = await this._pickFrom({ title: 'Checklist', search: false, items: [{ text: 'New Checklist', icon: 'checklist', value: 'new' }, ...lists.map(id => ({ text: this._stateName(id), sub: 'From Home Assistant', icon: 'todo', colour: 'var(--ce-orange)', value: id }))] });
    if (!v) return null;
    if (v.value !== 'new') {
      const r = await this._hass.callWS({ type: 'todo/item/list', entity_id: v.value });
      items = (r.items || []).filter(i => i.status !== 'completed').map(i => i.summary);
      if (!items.length) { this._toast('That list is empty.'); return null; }
    }
    return `${v.value !== 'new' ? `<div><b>${esc(v.text)}</b></div>` : ''}${items.map(t => `<div>☐ ${t ? esc(t) : '&nbsp;'}</div>`).join('')}<div><br></div>`;
  },

  _inviteSheet(cur) {
    return new Promise((resolve) => {
      const start = cur?.start || localInput(at(Math.min(new Date().getHours() + 1, 20), 0, 0));
      const end = cur?.end || localInput(new Date(start).getTime() + 3600000);
      let done = false;
      const sh = this._sheet({
        title: 'Event Invitation', action: 'Add',
        body: `<div class="sgroup xform">
          <div class="gr"><input class="gin left f-title" value="${esc(cur?.title || '')}" placeholder="Title"></div>
          <div class="gr"><input class="gin left f-loc" value="${esc(cur?.location || '')}" placeholder="Location"></div></div>
          <div class="sgroup xform" style="margin-top:14px">
          <div class="gr"><span class="gl">All Day</span>${this._sw('f-all', /^\d{4}-\d{2}-\d{2}$/.test(cur?.start || ''))}</div>
          <div class="gr"><span class="gl">Starts</span><input class="gin f-start dt" type="datetime-local" value="${esc(start.length > 10 ? start : `${start}T09:00`)}"></div>
          <div class="gr"><span class="gl">Ends</span><input class="gin f-end dt" type="datetime-local" value="${esc(end.length > 10 ? end : `${end}T10:00`)}"></div></div>
          <div class="sgroup xform" style="margin-top:14px"><textarea class="gta f-desc" placeholder="Notes">${esc(cur?.description || '')}</textarea></div>
          <div class="sfoot">Everyone in To and Cc is invited. Their mail app shows Accept, Maybe and Decline, and adds it to their calendar.</div>`,
        onAction: (api) => {
          const q = (s) => api.el.querySelector(s);
          const title = q('.f-title').value.trim();
          if (!title) { this._toast('Add a title.'); return false; }
          const all = q('.f-all').checked;
          let s = q('.f-start').value, e = q('.f-end').value;
          if (!s) { this._toast('Choose when it starts.'); return false; }
          if (all) { s = s.slice(0, 10); e = e ? e.slice(0, 10) : s; const d = new Date(`${e}T00:00`); d.setDate(d.getDate() + 1); e = localInput(d.getTime()).slice(0, 10); }
          else if (e && new Date(e) <= new Date(s)) { this._toast('It has to end after it starts.'); return false; }
          done = true;
          resolve({ title, start: s, end: e || null, location: q('.f-loc').value.trim(), description: q('.f-desc').value.trim() });
          return true;
        },
      });
      sh.onClose = () => { if (!done) resolve(null); };
    });
  },

  _pollSheet(cur, subject) {
    return new Promise((resolve) => {
      let done = false;
      const choices = [...(cur?.choices || ['', ''])];
      const sh = this._sheet({
        title: 'Voting Buttons', action: 'Add',
        body: `<div class="sgroup xform"><div class="gr"><input class="gin left f-q" value="${esc(cur?.question || subject || '')}" placeholder="Question"></div></div>
          <div class="sh">Choices</div><div class="sgroup xform f-ch"></div>
          <div class="sgroup" style="margin-top:14px"><div class="gr blue" role="button" data-add="1"><span class="gl">Add a Choice</span></div></div>
          <div class="sfoot">Each choice is a button in the email. Tapping one opens a reply that just needs sending, and the votes are counted for you here. Works in every mail app.</div>`,
        onAction: (api) => {
          const list = [...api.el.querySelectorAll('.f-c')].map(i => i.value.trim()).filter(Boolean);
          if (list.length < 2) { this._toast('Add at least two choices.'); return false; }
          done = true;
          resolve({ question: api.el.querySelector('.f-q').value.trim(), choices: [...new Set(list)].slice(0, 8) });
          return true;
        },
      });
      const box = sh.el.querySelector('.f-ch');
      const draw = () => {
        box.innerHTML = choices.map((c, i) => `<div class="gr choice-row"><input class="gin left f-c" data-i="${i}" value="${esc(c)}" placeholder="Choice ${i + 1}">${choices.length > 2 ? `<button data-rm="${i}" aria-label="Remove">${ICON.x}</button>` : ''}</div>`).join('');
      };
      draw();
      sh.el.addEventListener('input', (e) => { if (e.target.classList.contains('f-c')) choices[+e.target.dataset.i] = e.target.value; });
      sh.el.addEventListener('click', (e) => {
        if (e.target.closest('[data-add]') && choices.length < 8) { choices.push(''); draw(); box.querySelectorAll('.f-c')[choices.length - 1]?.focus(); }
        const rm = e.target.closest('[data-rm]')?.dataset.rm;
        if (rm !== undefined) { choices.splice(+rm, 1); draw(); }
      });
      sh.onClose = () => { if (!done) resolve(null); };
    });
  },

  _extrasChips(st) {
    const chip = (k, icon, text) => `<span class="xchip">${ICON[icon]}<span>${esc(text)}</span><button data-xrm="${k}" aria-label="Remove">${ICON.x}</button></span>`;
    return [
      st.invite ? chip('invite', 'calendar', `${st.invite.title}: ${ceWhen(st.invite, this._hass)}`) : '',
      st.poll ? chip('poll', 'poll', `Vote: ${st.poll.choices.join(', ')}`) : '',
      st.readReceipt ? chip('receipt', 'receipt', 'Read receipt asked for') : '',
    ].join('');
  },

  // ── Send Later: a time, or when you arrive or leave somewhere ────────
  async _pickWhen(anchor) {
    const zones = Object.keys(this._hass.states).filter(id => id.startsWith('zone.')).sort((a, b) => (a === 'zone.home' ? -1 : b === 'zone.home' ? 1 : ceZoneName(this._hass, a).localeCompare(ceZoneName(this._hass, b))));
    if (!this._s.person || !zones.length) {
      const ts = await this._pickTime('Send Later', 'Schedule');
      return ts ? { at: ts } : null;
    }
    const zitems = (ev) => zones.map(z => ({ text: ceZoneName(this._hass, z), value: `${ev}|${z}`, icon: z === 'zone.home' ? 'house' : 'pin' }));
    const v = await this._menu(anchor, [
      { text: 'Choose a Time…', value: 'time', icon: 'clock' },
      { sep: true },
      { text: 'When I Arrive…', value: 'arrive', icon: 'pin', sub: zitems('arrive') },
      { text: 'When I Leave…', value: 'leave', icon: 'pin', sub: zitems('leave') },
    ]);
    if (!v) return null;
    if (v === 'time') { const ts = await this._pickTime('Send Later', 'Schedule'); return ts ? { at: ts } : null; }
    const [event, zone] = v.split('|');
    return { place: { event, zone } };
  },
  _whenText(x) {
    if (x?.place && !x.at) return `When you ${x.place.event === 'arrive' ? 'arrive at' : 'leave'} ${x.place.name ? (x.place.name === 'home' ? 'Home' : x.place.name) : ceZoneName(this._hass, x.place.zone)}`;
    return fmtWhen(x.at, this._hass);
  },

  // ── Undo Send ────────────────────────────────────────────────────────
  _undoDelay() { return Number(this._s.prefs?.undo_send) || 0; },
  _sendingToast(item, delay, reopen) {
    this._root.querySelector('.toast')?.remove();
    const t = this._el(`<div class="toast g undo"><span>Sending…</span><button>Undo</button></div>`);
    let undone = false;
    t.querySelector('button').addEventListener('click', async () => {
      if (undone) return;
      undone = true; t.remove();
      try { const p = await this._call('send/undo', { item }); reopen(p); this._toast('Not sent'); } catch (err) { this._toast('Too late: it’s been sent.'); }
    });
    this._root.appendChild(t);
    setTimeout(() => { if (!undone) { t.querySelector('span').textContent = 'Sent'; t.querySelector('button').remove(); setTimeout(() => t.remove(), 1500); } }, delay * 1000);
  },

  // ── reading: invitations, votes and read receipts ────────────────────
  _extrasBanners(m, st) {
    let html = '';
    if (m.receipt_to && !m.receipt_sent && !st.receiptDismissed) {
      html += `<div class="banner remind">${ICON.receipt}<span>${esc(whoShort((m.from || [])[0]))} asked to know when you’ve read this.</span><button data-x="receipt">Send Receipt</button><button data-x="noreceipt" style="color:var(--ce-text2)">Not Now</button></div>`;
    }
    const inv = m.invite;
    if (inv) {
      const mine = st.rsvp || inv.replied?.status || (inv.my_status !== 'NEEDS-ACTION' ? inv.my_status : '');
      html += `<div class="xcard"><div class="xk">${ICON.calendar}${inv.cancelled ? 'Cancelled' : inv.method === 'REPLY' ? 'Reply' : 'Invitation'}</div>
        <div class="xt sel">${esc(inv.title || '(No title)')}</div>
        <div class="xs sel">${esc(ceWhen(inv, this._hass))}${inv.location ? `<br>${esc(inv.location)}` : ''}${inv.organizer ? `<br>From ${esc(inv.organizer.name || inv.organizer.email)}` : ''}${inv.attendees?.length > 1 ? ` · ${inv.attendees.length} invited` : ''}</div>
        ${inv.method === 'REPLY' ? `<div class="xs" style="margin-top:6px">${esc((inv.attendees || []).map(a => `${a.name || a.email}: ${RSVP[a.status] || a.status}`).join(', '))}</div>` : ''}
        <div class="xbtns">${!inv.cancelled && inv.method === 'REQUEST' && inv.organizer ? ['ACCEPTED', 'TENTATIVE', 'DECLINED'].map(s => `<button data-x="rsvp" data-s="${s}" class="${mine === s ? 'on' : ''}">${{ ACCEPTED: 'Accept', TENTATIVE: 'Maybe', DECLINED: 'Decline' }[s]}</button>`).join('') : ''}
          ${!inv.cancelled ? '<button class="plain" data-x="addcal">Add to Calendar</button>' : ''}</div>
        ${mine ? `<div class="xs" style="margin-top:8px">You replied: ${esc(RSVP[mine] || mine)}</div>` : ''}</div>`;
    }
    const p = m.poll;
    if (p) {
      const total = Object.values(p.counts || {}).reduce((a, b) => a + b, 0);
      html += `<div class="xcard poll"><div class="xk">${ICON.poll}Votes</div><div class="xt">${esc(p.question)}</div><div class="xs">${total} vote${total === 1 ? '' : 's'} so far</div>
        ${p.choices.map(c => { const n = p.counts?.[c] || 0; const who2 = (p.voters || []).filter(x => x.choice === c).map(x => x.name || x.email); return `<div class="pbar"><div class="pl"><b>${esc(c)}</b><span>${n}</span></div><div class="pt"><i style="width:${total ? Math.round(n / total * 100) : 0}%"></i></div>${who2.length ? `<div class="pv">${esc(who2.join(', '))}</div>` : ''}</div>`; }).join('')}</div>`;
    }
    return html;
  },

  async _extrasClick(btn, st, { draw }) {
    const x = btn.dataset.x, m = st.m, it = st.it;
    try {
      if (x === 'receipt') { await this._call('receipt/send', it); m.receipt_sent = true; this._toast('Read receipt sent'); draw(); }
      if (x === 'noreceipt') { st.receiptDismissed = true; draw(); }
      if (x === 'rsvp') {
        const s = btn.dataset.s;
        btn.disabled = true;
        await this._call('invite/reply', { ...it, status: s });
        st.rsvp = s;
        this._toast(`Replied: ${RSVP[s]}`);
        draw();
        if (s !== 'DECLINED' && Object.keys(this._hass.states).some(id => id.startsWith('calendar.')) && await this._confirm('Add to Calendar?', 'Add this event to a calendar in Home Assistant too?', 'Add')) this._addFound({ kind: 'event', title: m.invite.title, start: m.invite.start, end: m.invite.end, location: m.invite.location });
      }
      if (x === 'addcal') this._addFound({ kind: 'event', title: m.invite.title, start: m.invite.start, end: m.invite.end, location: m.invite.location });
    } catch (err) { btn.disabled = false; this._err(err); }
  },

  // a whole conversation as one PDF
  async _exportConversation(conv, current) {
    this._toast('Getting the conversation ready…');
    const msgs = [];
    for (const c of conv) {
      try { msgs.push(c.uid === current?.uid && c.folder === current?.folder && current.m ? current.m : await this._call('message', { account: c.account, folder: c.folder, uid: c.uid, remote: false, mark_seen: false })); } catch (e) { /* left out */ }
    }
    if (!msgs.length) { this._toast('Couldn’t open the conversation.'); return; }
    msgs.sort((a, b) => a.date - b.date);
    this._savePdf(msgs, this._pdfName(String(msgs[0].subject || 'Conversation').replace(/^((re|fwd?|aw|sv):\s*)+/i, '')), 'Conversation', { conversation: true });
  },

  // what's in a picture, read out by the AI
  async _describePicture(box, args) {
    box.hidden = false;
    box.innerHTML = '<span class="spin small" style="border-top-color:#fff"></span> Looking at the picture…';
    try {
      const r = await this._call('ai/describe', args);
      box.textContent = r.detail || r.short || 'Nothing to describe.';
    } catch (err) { box.textContent = err.message || 'Couldn’t describe it.'; }
  },

  // the reader and composer, with the account's colour as the accent when chosen
  _pg_reader(data) {
    const p = _cePgReader.call(this, data);
    this._accountAccent(p.el, data.account);
    return p;
  },
  _pg_compose(o) {
    const p = _cePgCompose.call(this, o);
    this._accountAccent(p.el, this._defaultAccount(o.account)?.id);
    return p;
  },
});
// ── Save as PDF ─────────────────────────────────────────────────────────────
// The Home Assistant app on iPhone and iPad can't print from a web page, so an email (or a
// whole conversation) is made into a PDF on the device, as real text with jsPDF (loaded from
// cdnjs the first time, with the Noto Sans font), and shown in a preview with Download.
const PDF_MAX_PAGES = 60;
const PDF_FONT_BASE = 'https://cdn.jsdelivr.net/npm/@expo-google-fonts/noto-sans@0.4.2/';
const PDF_IMG_RUN = /(\p{Extended_Pictographic}(?:\uFE0F|\p{Emoji_Modifier}|\u200D\p{Extended_Pictographic}\uFE0F?)*|[\u{1F1E6}-\u{1F1FF}]{2}|[\u0590-\u08FF\u0900-\u0DFF\u0E00-\u0E7F\u1100-\u11FF\u2E80-\u9FFF\uAC00-\uD7AF\uF900-\uFAFF\uFF00-\uFFEF\u{20000}-\u{2FFFF}]+)/gu;
const CE_PDF_FONTS = {};

// a CSS colour as [r, g, b] (null for none, transparent or something it can't read)
function colour(v) {
  v = String(v || '').trim().toLowerCase();
  if (!v || /transparent|inherit|initial|currentcolor|none|url\(/.test(v) && !/#|rgb/.test(v)) return null;
  const m = v.match(/#([0-9a-f]{3}|[0-9a-f]{6})\b/) || null;
  if (m) { let h = m[1]; if (h.length === 3) h = h.split('').map(x => x + x).join(''); return [0, 2, 4].map(i => parseInt(h.slice(i, i + 2), 16)); }
  const r = v.match(/rgba?\(\s*(\d+)[\s,]+(\d+)[\s,]+(\d+)(?:[\s,/]+([\d.]+))?/);
  if (r) return r[4] !== undefined && parseFloat(r[4]) < 0.2 ? null : [+r[1], +r[2], +r[3]];
  const named = { black: [0, 0, 0], white: [255, 255, 255], red: [255, 0, 0], blue: [0, 0, 255], green: [0, 128, 0], gray: [128, 128, 128], grey: [128, 128, 128], navy: [0, 0, 128], orange: [255, 165, 0], purple: [128, 0, 128], silver: [192, 192, 192], maroon: [128, 0, 0], teal: [0, 128, 128] };
  const w = v.split(/\s+/).find(x => named[x]);
  return w ? named[w] : null;
}
function luminance(c) { return (0.2126 * c[0] + 0.7152 * c[1] + 0.0722 * c[2]) / 255; }

function ceScript(src, test) {
  ceScript.cache = ceScript.cache || {};
  if (test()) return Promise.resolve();
  if (ceScript.cache[src]) return ceScript.cache[src];
  ceScript.cache[src] = new Promise((res, rej) => {
    const s = document.createElement('script');
    s.src = src;
    const t = setTimeout(() => { delete ceScript.cache[src]; rej(new Error('The PDF tools took too long to load. Check the internet connection and try again.')); }, 20000);
    s.onload = () => { clearTimeout(t); if (test()) res(); else { delete ceScript.cache[src]; rej(new Error('The PDF tools didn’t start.')); } };
    s.onerror = () => { clearTimeout(t); delete ceScript.cache[src]; rej(new Error('Couldn’t load the PDF tools. Check the internet connection and try again.')); };
    document.head.appendChild(s);
  });
  return ceScript.cache[src];
}

function ceSaveBlob(blob, name) {
  const u = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = u; a.download = name; a.rel = 'noopener';
  document.body.appendChild(a); a.click(); a.remove();
  setTimeout(() => URL.revokeObjectURL(u), 60000);
}

Object.assign(CrowMessengerEmail.prototype, {
  // The preview: a sheet over the whole screen with every page (drawn by PDF.js,
  // scroll, pinch or double-tap to zoom), Close, and Download.
  _openPdfPreview(title) {
    const dark = this._isDark();
    const glass = this.getAttribute('data-style') === 'glass';
    const accent = getComputedStyle(this).getPropertyValue('--ce-accent').trim() || '#0A84FF';
    const overlay = document.createElement('div');
    overlay.style.cssText = 'position:fixed;inset:0;z-index:10060;display:flex;align-items:center;justify-content:center;padding:16px;'
      + 'background:' + (glass ? (dark ? 'rgba(0,0,0,0.32)' : 'rgba(255,255,255,0.16)') : 'rgba(0,0,0,0.6)') + ';backdrop-filter:blur(6px);-webkit-backdrop-filter:blur(6px);animation:cePdfFade 0.18s ease;';
    const style = document.createElement('style');
    style.textContent = '@keyframes cePdfFade{from{opacity:0}to{opacity:1}}@keyframes cePdfUp{from{transform:translateY(12px) scale(0.96);opacity:0}to{transform:none;opacity:1}}@keyframes cePdfSpin{to{transform:rotate(360deg)}}';
    const card = document.createElement('div');
    card.style.cssText = 'position:relative;width:100%;max-width:560px;max-height:calc(100vh - 32px);display:flex;flex-direction:column;overflow:hidden;font-family:-apple-system,BlinkMacSystemFont,sans-serif;animation:cePdfUp 0.22s cubic-bezier(0.34,1.4,0.64,1);'
      + (glass
        ? 'border-radius:30px;background:' + (dark ? 'linear-gradient(160deg,rgba(255,255,255,0.15),rgba(255,255,255,0.05))' : 'linear-gradient(160deg,rgba(255,255,255,0.7),rgba(255,255,255,0.45))') + ';'
          + 'backdrop-filter:blur(28px) saturate(2) brightness(' + (dark ? '0.88' : '1.04') + ');-webkit-backdrop-filter:blur(28px) saturate(2) brightness(' + (dark ? '0.88' : '1.04') + ');'
          + 'border:1px solid ' + (dark ? 'rgba(255,255,255,0.22)' : 'rgba(255,255,255,0.85)') + ';'
          + 'box-shadow:0 30px 80px rgba(0,0,0,' + (dark ? '0.5' : '0.2') + '),inset 0 1px 0 rgba(255,255,255,' + (dark ? '0.36' : '1') + ');'
        : 'border-radius:24px;background:' + (dark ? 'rgba(40,40,42,0.96)' : 'rgba(242,242,247,0.97)') + ';border:1px solid ' + (dark ? 'rgba(255,255,255,0.15)' : 'rgba(0,0,0,0.08)') + ';box-shadow:0 24px 64px rgba(0,0,0,0.5);');
    const ink = dark ? '#fff' : '#000';
    const head = document.createElement('div');
    head.style.cssText = 'position:relative;display:flex;align-items:center;justify-content:space-between;gap:12px;padding:20px 20px 0;margin-bottom:16px;flex-shrink:0;min-height:32px;';
    head.innerHTML = '<span class="ce-pdf-close" role="button" style="color:' + (glass ? (dark ? '#fff' : accent) : (dark ? '#63b3ed' : accent)) + ';font-size:15px;cursor:pointer;padding:4px 0;">Close</span>'
      + '<span style="font-size:15px;font-weight:600;color:' + ink + ';flex:1;text-align:center;overflow:hidden;white-space:nowrap;text-overflow:ellipsis;">' + esc(title) + '</span><span style="width:40px"></span>';
    const body = document.createElement('div');
    body.style.cssText = 'position:relative;padding:0 20px 20px;overflow-y:auto;overflow-x:hidden;-webkit-overflow-scrolling:touch;flex:1;min-height:0;';
    body.addEventListener('touchmove', e => e.stopPropagation(), { passive: true });
    const frame = document.createElement('div');
    frame.style.cssText = 'width:100%;height:58vh;min-height:340px;border-radius:' + (glass ? 18 : 12) + 'px;overflow:hidden;background:#fff;margin-bottom:10px;border:1px solid ' + (dark ? 'rgba(255,255,255,0.18)' : 'rgba(0,0,0,0.08)') + ';display:flex;align-items:center;justify-content:center;flex-direction:column;gap:10px;';
    frame.innerHTML = '<div style="width:28px;height:28px;border:2.5px solid rgba(0,122,255,0.2);border-top-color:#007AFF;border-radius:50%;animation:cePdfSpin 0.8s linear infinite;"></div><div style="font-size:12px;color:#888;">Preparing PDF…</div>'
      + '<div class="ce-pdf-status" style="font-size:11px;color:#aaa;min-height:14px;text-align:center;padding:0 24px;"></div>'
      + '<div class="ce-pdf-bar" style="display:none;width:160px;height:4px;border-radius:2px;background:rgba(0,122,255,0.15);overflow:hidden;"><div style="height:100%;width:0;background:#007AFF;border-radius:2px;transition:width 0.25s ease;"></div></div>';
    const dl = document.createElement('button');
    dl.textContent = 'Download';
    dl.disabled = true;
    dl.style.cssText = 'width:100%;padding:12px;border:none;color:#fff;font-size:14px;font-weight:700;cursor:pointer;font-family:inherit;opacity:0.4;'
      + (glass ? 'border-radius:999px;background:' + accent + ';box-shadow:0 8px 22px rgba(0,0,0,0.2),inset 0 1px 0 rgba(255,255,255,0.45);' : 'border-radius:12px;background:' + accent + ';');
    // Attach to New Email: the PDF goes straight into a new email
    const attach = document.createElement('button');
    attach.textContent = 'Attach to New Email';
    attach.disabled = true;
    attach.style.cssText = 'width:100%;padding:12px;border:none;color:#fff;font-size:14px;font-weight:700;cursor:pointer;font-family:inherit;opacity:0.4;'
      + (glass ? 'border-radius:999px;background:' + accent + ';box-shadow:0 8px 22px rgba(0,0,0,0.2),inset 0 1px 0 rgba(255,255,255,0.45);' : 'border-radius:12px;background:' + accent + ';');
    // Download becomes the quieter of the two
    dl.style.background = dark ? 'rgba(255,255,255,0.12)' : 'rgba(118,118,128,0.14)';
    dl.style.color = dark ? '#fff' : accent;
    dl.style.boxShadow = 'none';
    const btns = document.createElement('div');
    btns.style.cssText = 'display:flex;flex-wrap:wrap;gap:10px;';
    dl.style.flex = '1 1 140px'; attach.style.flex = '1 1 180px'; dl.style.whiteSpace = attach.style.whiteSpace = 'nowrap';
    btns.appendChild(dl); btns.appendChild(attach);
    body.appendChild(frame); body.appendChild(btns);
    card.appendChild(style); card.appendChild(head); card.appendChild(body);
    overlay.appendChild(card);
    let closed = false, blobUrl = null;
    const cleanups = [];
    const close = () => {
      if (closed) return;
      closed = true;
      overlay.style.transition = 'opacity 0.18s ease'; overlay.style.opacity = '0';
      setTimeout(() => { overlay.remove(); if (blobUrl) URL.revokeObjectURL(blobUrl); cleanups.forEach(fn => { try { fn(); } catch (e) { /* */ } }); }, 180);
    };
    head.querySelector('.ce-pdf-close').addEventListener('click', close);
    overlay.addEventListener('click', e => { if (e.target === overlay) close(); });
    const onKey = (e) => { if (e.key === 'Escape') close(); };
    document.addEventListener('keydown', onKey);
    cleanups.push(() => document.removeEventListener('keydown', onKey));
    overlay.classList.add('ce-pdf-ov');
    (this._full && this._card ? this._card : document.body).appendChild(overlay);   // full screen: above the card, not behind it
    return {
      get closed() { return closed; },
      onClose: (fn) => cleanups.push(fn),
      status: (text, done, total) => {
        const st = frame.querySelector('.ce-pdf-status'), bar = frame.querySelector('.ce-pdf-bar');
        if (closed || !st) return;
        st.textContent = text + (total ? ` ${done} of ${total}` : '');
        if (bar) { bar.style.display = total ? 'block' : 'none'; if (total) bar.firstChild.style.width = `${Math.round(done / total * 100)}%`; }
      },
      show: (pdf, filename) => {
        if (closed) return;
        blobUrl = pdf.output('bloburl');
        const buf = pdf.output('arraybuffer');
        const showFrame = () => {
          if (closed) return;
          frame.innerHTML = ''; frame.style.display = 'block';
          const f = document.createElement('iframe');
          f.src = blobUrl; f.title = 'PDF preview'; f.style.cssText = 'width:100%;height:100%;border:none;';
          frame.appendChild(f);
        };
        this._renderPDFPages(frame, buf, { isClosed: () => closed, onCleanup: fn => cleanups.push(fn) })
          .catch((e) => { console.warn('Crow Messenger Email: page viewer unavailable', e); showFrame(); });
        dl.disabled = false; dl.style.opacity = '1';
        attach.disabled = false; attach.style.opacity = '1';
        attach.onclick = () => {
          const file = new File([new Blob([buf.slice(0)], { type: 'application/pdf' })], filename, { type: 'application/pdf' });
          close();
          this._compose({ subject: filename.replace(/\.pdf$/i, ''), files: [file], changed: true });
        };
        dl.onclick = () => {
          const a = document.createElement('a');
          a.href = blobUrl; a.download = filename;
          document.body.appendChild(a); a.click(); a.remove();
          dl.textContent = 'Downloaded';
          setTimeout(() => { dl.textContent = 'Download'; }, 1500);
        };
      },
      fail: (msg) => {
        if (closed) return;
        frame.style.background = 'transparent';
        frame.style.border = 'none';
        frame.innerHTML = '<div style="padding:30px 20px;text-align:center;font-size:15px;line-height:1.4;color:' + (dark ? 'rgba(235,235,245,0.75)' : 'rgba(60,60,67,0.75)') + '"><div style="font-size:17px;font-weight:700;color:' + ink + ';margin-bottom:6px">Couldn’t Make the PDF</div>' + esc(msg) + '</div>';
        dl.style.display = 'none';
        attach.style.display = 'none';
      },
    };
  },

  // Makes the PDF from the emails as real text, then shows it in
  // the preview. Pictures in the email are added; emoji and scripts the font can't draw are drawn
  // by the phone as small pictures.
  async _savePdf(msgs, filename, title = 'Email', { conversation = false } = {}) {
    const preview = this._openPdfPreview(title);
    const timeout = new Promise((_, rej) => setTimeout(() => rej(new Error('Making the PDF took too long. Try again.')), 90000));
    try {
      const pdf = await Promise.race([this._buildPdf(msgs, { conversation, status: preview.status, closed: () => preview.closed }), timeout]);
      if (!pdf || preview.closed) return;
      preview.status('Loading the page viewer…');
      preview.show(pdf, filename);
    } catch (err) {
      console.error('Crow Messenger Email PDF', err);
      preview.fail(err?.message || 'Something went wrong while making the PDF.');
    }
  },

  async _pdfFonts() {
    if (CE_PDF_FONTS.data !== undefined) return CE_PDF_FONTS.data;
    const get = async (path) => {
      const r = await fetch(PDF_FONT_BASE + path);
      if (!r.ok) throw new Error(r.status);
      const bytes = new Uint8Array(await r.arrayBuffer());
      let bin = '';
      for (let i = 0; i < bytes.length; i += 0x8000) bin += String.fromCharCode.apply(null, bytes.subarray(i, i + 0x8000));
      return btoa(bin);
    };
    try {
      const [reg, bold, italic] = await Promise.race([
        Promise.all([get('400Regular/NotoSans_400Regular.ttf'), get('700Bold/NotoSans_700Bold.ttf'), get('400Regular_Italic/NotoSans_400Regular_Italic.ttf').catch(() => null)]),
        new Promise((_, rej) => setTimeout(() => rej(new Error('slow')), 15000)),
      ]);
      CE_PDF_FONTS.data = { reg, bold, italic };
    } catch (e) { CE_PDF_FONTS.data = null; }
    return CE_PDF_FONTS.data;
  },

  // The email's HTML as blocks: lines of styled text (colour, size, bold, links, alignment),
  // pictures, buttons and rules. Close to how the email looks, without a browser drawing it.
  _pdfBlocks(html) {
    const doc = new DOMParser().parseFromString(`<body>${html || ''}</body>`, 'text/html');
    const blocks = [];
    let cur = null;
    const BLOCK = /^(P|DIV|H[1-6]|LI|UL|OL|BLOCKQUOTE|TABLE|TR|TD|TH|PRE|SECTION|ARTICLE|HEADER|FOOTER|CENTER|ADDRESS|DL|DT|DD|FIGURE|FIGCAPTION|TBODY|THEAD|TFOOT|MAIN|NAV)$/;
    const sty = (el) => el.getAttribute?.('style') || '';
    const prop = (el, name) => { const m = sty(el).match(new RegExp(`(?:^|;)\\s*${name}\\s*:\\s*([^;]+)`, 'i')); return m ? m[1].trim().replace(/\s*!important$/i, '') : ''; };
    const flush = () => {
      if (cur && cur.runs.some(r => r.t.trim() || r.t === '\n')) {
        while (cur.runs.length && cur.runs[cur.runs.length - 1].t === '\n') cur.runs.pop();
        blocks.push(cur);
      }
      cur = null;
    };
    const start = (ctx) => { if (!cur) cur = { type: 'text', runs: [], indent: ctx.indent, quote: ctx.quote, pre: ctx.pre, align: ctx.align }; return cur; };
    const hidden = (el) => /display\s*:\s*none|visibility\s*:\s*hidden|mso-hide\s*:\s*all|max-height\s*:\s*0|font-size\s*:\s*0(px)?\s*(;|$)|opacity\s*:\s*0(\.0+)?\s*(;|$)/i.test(sty(el)) || el.hasAttribute?.('hidden');
    const textOf = (el) => (el.textContent || '').replace(/\s+/g, ' ').trim();
    // an email "button": a link with a background or border (or a link that's the only thing in a coloured cell)
    const buttonOf = (a) => {
      const bgA = colour(prop(a, 'background-color') || prop(a, 'background'));
      const border = /\d/.test(prop(a, 'border')) && !/none|0px/.test(prop(a, 'border'));
      let bg = bgA;
      if (!bg) {
        for (let p = a.parentElement, i = 0; p && i < 3; p = p.parentElement, i++) {
          if (textOf(p) !== textOf(a)) break;
          bg = colour(p.getAttribute('bgcolor') || prop(p, 'background-color') || prop(p, 'background'));
          if (bg) break;
        }
      }
      if (!bg && !border) return null;
      if (bg && luminance(bg) > 0.93) bg = null;   // a white "button" on a white page: an outline instead
      return { bg, fg: colour(prop(a, 'color')) || (bg ? (luminance(bg) < 0.6 ? [255, 255, 255] : [17, 17, 17]) : [17, 17, 17]), outline: !bg };
    };
    const walk = (node, st, ctx) => {
      if (node.nodeType === 3) {
        let t = node.nodeValue || '';
        if (!ctx.pre) t = t.replace(/[\s​-‍͏­]+/g, (m) => /\S/.test(m.replace(/[​-‍͏­]/g, '')) ? m : (/\s/.test(m) ? ' ' : ''));
        if (!ctx.pre) t = t.replace(/[​-‍͏­]/g, '').replace(/\s+/g, ' ');
        if (!t) return;
        const b = start(ctx);
        if (!ctx.pre && t === ' ' && (!b.runs.length || /\s$/.test(b.runs[b.runs.length - 1].t))) return;
        b.runs.push({ t, ...st });
        return;
      }
      if (node.nodeType !== 1) return;
      const tag = node.tagName;
      if (/^(STYLE|SCRIPT|HEAD|TITLE|META|LINK|NOSCRIPT|TEMPLATE|SVG)$/.test(tag) || hidden(node)) return;
      if (node.classList?.contains('ce-print')) return;
      if (tag === 'BR') { start(ctx).runs.push({ t: '\n', ...st }); return; }
      if (tag === 'HR') { flush(); blocks.push({ type: 'hr', indent: ctx.indent }); return; }
      if (tag === 'IMG') {
        const src = node.getAttribute('src') || '';
        const w = parseInt(node.getAttribute('width') || prop(node, 'width'), 10), h = parseInt(node.getAttribute('height') || prop(node, 'height'), 10);
        if (!src || node.hasAttribute('data-blocked') || (w && w <= 3) || (h && h <= 3)) return;
        flush(); blocks.push({ type: 'img', src, w: w || 0, h: h || 0, indent: ctx.indent, link: st.link, align: node.getAttribute('align') === 'right' ? 'right' : ctx.align, alt: node.getAttribute('alt') || '' });
        return;
      }
      let s2 = st, c2 = ctx;
      const al = (node.getAttribute('align') || prop(node, 'text-align') || '').toLowerCase();
      if (/^(center|right|left)$/.test(al)) c2 = { ...c2, align: al };
      if (tag === 'CENTER') c2 = { ...c2, align: 'center' };
      const col = colour(prop(node, 'color'));
      if (col) s2 = { ...s2, color: col };
      const fs = prop(node, 'font-size').match(/^([\d.]+)\s*(px|pt)?$/i);
      if (fs) s2 = { ...s2, size: Math.max(7, Math.min(30, parseFloat(fs[1]) * (fs[2]?.toLowerCase() === 'pt' ? 1 : 0.75))) };
      if (/^(B|STRONG|TH)$/.test(tag) || /^(bold|[6-9]00)$/i.test(prop(node, 'font-weight'))) s2 = { ...s2, bold: true };
      if (/^(I|EM|CITE)$/.test(tag) || /italic/i.test(prop(node, 'font-style'))) s2 = { ...s2, italic: true };
      if (/^H[1-6]$/.test(tag)) s2 = { ...s2, bold: true, size: s2.size && fs ? s2.size : [0, 20, 17, 14.5, 13, 12, 11][+tag[1]] };
      if (tag === 'A' && /^(https?:|mailto:|tel:)/i.test(node.getAttribute('href') || '')) {
        const href = node.getAttribute('href');
        const btn = textOf(node) && !node.querySelector('img') ? buttonOf(node) : null;
        if (btn) { flush(); blocks.push({ type: 'button', text: textOf(node), href, ...btn, size: s2.size || 11, align: c2.align, indent: c2.indent }); return; }
        s2 = { ...s2, link: href };
      }
      if (tag === 'BLOCKQUOTE') c2 = { ...c2, indent: c2.indent + 12, quote: true };
      if (tag === 'UL' || tag === 'OL') c2 = { ...c2, indent: c2.indent + 14, list: tag, n: 0 };
      if (tag === 'PRE') c2 = { ...c2, pre: true };
      const isBlock = BLOCK.test(tag);
      if (isBlock) flush();
      if (tag === 'LI') { ctx.n = (ctx.n || 0) + 1; start(c2).runs.push({ t: ctx.list === 'OL' ? `${ctx.n}. ` : '• ', ...st }); }
      for (const ch of node.childNodes) walk(ch, s2, c2);
      if (isBlock) flush();
    };
    walk(doc.body, {}, { indent: 0, quote: false, pre: false, align: 'left' });
    flush();
    return blocks;
  },

  async _buildPdf(msgs, { conversation, status, closed }) {
    status('Loading the PDF tools…');
    await ceScript('https://cdnjs.cloudflare.com/ajax/libs/jspdf/2.5.1/jspdf.umd.min.js', () => !!window.jspdf?.jsPDF);
    if (closed()) return null;
    status('Loading the fonts…');
    const fonts = await this._pdfFonts();
    if (closed()) return null;
    const { jsPDF } = window.jspdf;
    const doc = new jsPDF({ unit: 'pt', format: 'a4', compress: true });
    let face = 'helvetica', hasItalic = true;
    if (fonts) {
      doc.addFileToVFS('NotoSans-Regular.ttf', fonts.reg); doc.addFont('NotoSans-Regular.ttf', 'Noto', 'normal');
      doc.addFileToVFS('NotoSans-Bold.ttf', fonts.bold); doc.addFont('NotoSans-Bold.ttf', 'Noto', 'bold');
      if (fonts.italic) { doc.addFileToVFS('NotoSans-Italic.ttf', fonts.italic); doc.addFont('NotoSans-Italic.ttf', 'Noto', 'italic'); } else hasItalic = false;
      face = 'Noto';
    }
    const W = doc.internal.pageSize.getWidth(), H = doc.internal.pageSize.getHeight(), M = 42;
    const BASE = 10.5;
    let y = M;
    const clean = (s) => face === 'Noto' ? String(s ?? '') : String(s ?? '')
      .replace(/[‘’]/g, "'").replace(/[“”]/g, '"').replace(/[–—]/g, '-').replace(/…/g, '...').replace(/[^\x09\x0A\x0D\x20-\x7E\xA0-\xFF]/g, '');
    const setFont = (size, st = {}) => { doc.setFont(face, st.bold ? 'bold' : st.italic && hasItalic ? 'italic' : 'normal'); doc.setFontSize(size); };
    const ensure = (h) => { if (y + h > H - M) { doc.addPage(); y = M; return true; } return false; };
    const emojiCache = new Map();
    const runImage = (s, size, col) => {
      const key = `${s}|${size}|${col}`;
      if (emojiCache.has(key)) return emojiCache.get(key);
      const scale = 4, px = size * scale;
      const cv = document.createElement('canvas'), g = cv.getContext('2d');
      const font = `${px}px -apple-system, "Apple Color Emoji", "Segoe UI Emoji", "Noto Color Emoji", "Segoe UI", Roboto, "Noto Sans", sans-serif`;
      g.font = font;
      const w = Math.max(1, Math.ceil(g.measureText(s).width));
      cv.width = w + 4; cv.height = Math.ceil(px * 1.35);
      g.font = font; g.textBaseline = 'middle'; g.fillStyle = col;
      g.fillText(s, 2, cv.height / 2);
      const out = { url: cv.toDataURL('image/png'), w: cv.width / scale, h: cv.height / scale };
      emojiCache.set(key, out);
      return out;
    };
    // styled runs, wrapped into lines that fit the width
    const layout = (runs, maxW, pre, base = BASE) => {
      const pieces = [];
      for (const r of runs) {
        const size = r.size || base;
        if (r.t === '\n') { pieces.push({ br: true, size }); continue; }
        setFont(size, r);
        clean(r.t).split(PDF_IMG_RUN).forEach((part, i) => {
          if (!part) return;
          if (i % 2 === 1) { const im = runImage(part, size, '#111'); pieces.push({ img: part, w: im.w, st: r, size }); return; }
          part.split(pre ? /(\n)/ : /(\s+)/).forEach(w => {
            if (!w) return;
            if (w === '\n') { pieces.push({ br: true, size }); return; }
            pieces.push({ t: w, w: doc.getTextWidth(w), space: !pre && /^\s+$/.test(w), st: r, size });
          });
        });
      }
      const lines = [];
      let line = [], lw = 0, lastSize = base;
      const push = () => {
        while (line.length && line[line.length - 1].space) lw -= line.pop().w;
        lines.push({ pieces: line, w: lw, size: line.length ? Math.max(...line.map(p => p.size)) : lastSize });
        line = []; lw = 0;
      };
      for (let p of pieces) {
        lastSize = p.size;
        if (p.br) { push(); continue; }
        if (p.space && !line.length) continue;
        if (lw + p.w > maxW && line.length) { push(); if (p.space) continue; }
        while (!p.img && p.w > maxW) {
          setFont(p.size, p.st);
          let n = p.t.length;
          while (n > 1 && doc.getTextWidth(p.t.slice(0, n)) > maxW - lw) n--;
          const a = p.t.slice(0, n);
          line.push({ ...p, t: a, w: doc.getTextWidth(a) }); lw += doc.getTextWidth(a); push();
          p = { ...p, t: p.t.slice(n), w: doc.getTextWidth(p.t.slice(n)) };
        }
        line.push(p); lw += p.w;
      }
      if (line.length) push();
      return lines;
    };
    const readable = (c) => (c && luminance(c) > 0.85 ? null : c);   // white text (on a coloured box in the email) would vanish on white paper
    const drawLines = (lines, x, maxW, { color = [17, 17, 17], quote = false, align = 'left' } = {}) => {
      for (const ln of lines) {
        const lh = ln.size * 1.42;
        ensure(lh);
        let cx = align === 'center' ? x + (maxW - ln.w) / 2 : align === 'right' ? x + maxW - ln.w : x;
        if (quote) { doc.setDrawColor(10, 132, 255); doc.setLineWidth(1.5); doc.line(x - 8, y, x - 8, y + lh); }
        for (const p of ln.pieces) {
          const st = p.st || {};
          const col = st.link && !st.color ? [10, 100, 214] : readable(st.color) || (quote ? [85, 85, 85] : color);
          const base = y + (lh - p.size * 1.42) + p.size * 1.05;
          if (p.img) { const im = runImage(p.img, p.size, `rgb(${col.join(',')})`); doc.addImage(im.url, 'PNG', cx, base - p.size * 1.02, im.w, im.h); }
          else if (!p.space) {
            setFont(p.size, st); doc.setTextColor(col[0], col[1], col[2]);
            doc.text(p.t, cx, base);
            if (st.link) doc.link(cx, y, p.w, lh, { url: st.link });
          }
          cx += p.w;
        }
        y += lh;
      }
    };
    const text = (t, size, st = {}, color, x = M) => drawLines(layout([{ t, ...st, size }], W - M - x, false), x, W - M - x, { color });
    // pictures from the web are fetched through Home Assistant (the sender doesn't see your address)
    const remote = [...new Set(msgs.flatMap(m => m.remote ? [...String(m.html_safe || '').matchAll(/<img[^>]+src="(https?:\/\/[^"]+)"/gi)].map(x => x[1].replace(/&amp;/g, '&')) : []))].slice(0, 80);
    let proxied = {};
    if (remote.length) { try { proxied = await this._call('pdf/images', { urls: remote }); } catch (e) { proxied = {}; } }
    const picture = async (b) => {
      try {
        let url = b.src.replace(/&amp;/g, '&');
        if (!/^data:image\//.test(url)) {
          const u = new URL(url, location.href);
          let href = u.href;
          if (u.origin !== location.origin) { href = proxied[url]; if (!href) return; }
          const r = await fetch(href);
          if (!r.ok) return;
          const blob = await r.blob();
          if (!/^image\//.test(blob.type) || /svg/.test(blob.type)) return;
          url = await ceDataUrl(blob);
        }
        const im = await ceLoadImage(url);
        if (im.naturalWidth <= 3 || im.naturalHeight <= 3) return;
        // as JPEG on white, so any picture type (and transparency) works
        const cv = document.createElement('canvas');
        const sc = Math.min(1, 1400 / Math.max(im.naturalWidth, 1));
        cv.width = Math.max(1, Math.round(im.naturalWidth * sc)); cv.height = Math.max(1, Math.round(im.naturalHeight * sc));
        const g = cv.getContext('2d'); g.fillStyle = '#fff'; g.fillRect(0, 0, cv.width, cv.height); g.drawImage(im, 0, 0, cv.width, cv.height);
        const maxW = W - 2 * M - b.indent;
        let w = Math.min(maxW, (b.w || im.naturalWidth) * 0.75);
        let h = b.w && b.h ? w * b.h / b.w : w * cv.height / cv.width;
        if (h > H - 2 * M) { h = H - 2 * M; w = h * cv.width / cv.height; }
        ensure(h + 6);
        const x = b.align === 'center' ? M + b.indent + (maxW - w) / 2 : b.align === 'right' ? W - M - w : M + b.indent;
        doc.addImage(cv.toDataURL('image/jpeg', 0.88), 'JPEG', x, y, w, h);
        if (b.link) doc.link(x, y, w, h, { url: b.link });
        y += h + 8;
      } catch (e) { /* left out */ }
    };
    const button = (b) => {
      const size = Math.min(14, Math.max(9, b.size || BASE));
      setFont(size, { bold: true });
      const label = clean(b.text);
      const maxW = W - 2 * M - b.indent;
      const tw = Math.min(doc.getTextWidth(label), maxW - 32);
      const bw = Math.min(maxW, tw + 36), bh = size * 2.4;
      ensure(bh + 10);
      const x = b.align === 'center' ? M + b.indent + (maxW - bw) / 2 : b.align === 'right' ? W - M - bw : M + b.indent;
      if (b.outline) { doc.setDrawColor(60, 60, 67); doc.setLineWidth(0.9); doc.roundedRect(x, y, bw, bh, bh / 2, bh / 2, 'S'); }
      else { doc.setFillColor(b.bg[0], b.bg[1], b.bg[2]); doc.roundedRect(x, y, bw, bh, bh / 2, bh / 2, 'F'); }
      const fg = b.outline ? (readable(b.fg) || [17, 17, 17]) : b.fg;
      doc.setTextColor(fg[0], fg[1], fg[2]);
      doc.text(label, x + bw / 2, y + bh / 2 + size * 0.36, { align: 'center', maxWidth: bw - 20 });
      doc.link(x, y, bw, bh, { url: b.href });
      y += bh + 10;
    };
    // ── the email as the browser lays it out ──
    // The email is laid out in a hidden frame at a typical email width, then everything is drawn
    // where the browser put it: coloured boxes, borders and rounded buttons, pictures, and every
    // word (as real text, in its own size, weight and colour). Pages are split between lines.
    const PX = 600, scale = (W - 2 * M) / PX;
    const rgba = (v) => {
      const r = String(v || '').match(/rgba?\(\s*([\d.]+)[\s,]+([\d.]+)[\s,]+([\d.]+)(?:[\s,/]+([\d.]+))?/);
      if (!r) return null;
      const a = r[4] === undefined ? 1 : parseFloat(r[4]);
      if (a < 0.05) return null;
      // see-through colours, mixed with the white page
      return [+r[1], +r[2], +r[3]].map(c => Math.round(c * a + 255 * (1 - a)));
    };
    const renderDom = async (html, proxied) => {
      const fr = document.createElement('iframe');
      fr.setAttribute('sandbox', 'allow-same-origin');
      fr.setAttribute('aria-hidden', 'true');
      fr.style.cssText = `position:fixed;left:-${PX + 400}px;top:0;width:${PX}px;height:200px;border:0;opacity:0;pointer-events:none`;
      // pictures from the web come through Home Assistant
      html = String(html || '').replace(/(<img\b[^>]*?\ssrc=")(https?:\/\/[^"]+)(")/gi, (all, a, u, b) => {
        const p = proxied[u.replace(/&amp;/g, '&')];
        return p ? a + p + b : `${a}${b} data-blocked="1"`;
      });
      // laid out in the PDF's own font, so every word fits its place exactly
      const ff = fonts ? `@font-face{font-family:CEPdf;src:url(data:font/ttf;base64,${fonts.reg});font-weight:100 500;font-style:normal}
        @font-face{font-family:CEPdf;src:url(data:font/ttf;base64,${fonts.bold});font-weight:600 900;font-style:normal}
        ${fonts.italic ? `@font-face{font-family:CEPdf;src:url(data:font/ttf;base64,${fonts.italic});font-style:italic}` : ''}
        *{font-family:CEPdf,"Apple Color Emoji","Segoe UI Emoji","Noto Color Emoji",sans-serif !important}` : '';
      fr.srcdoc = `<!DOCTYPE html><html><head><meta charset="utf-8"><style>${ff}
        html,body{margin:0;padding:0;background:#fff}
        body{width:${PX}px;font:15px/1.45 -apple-system,BlinkMacSystemFont,"Helvetica Neue",Helvetica,Arial,sans-serif;color:#111;word-wrap:break-word;overflow-wrap:anywhere;-webkit-text-size-adjust:100%}
        img{max-width:100%;height:auto}img[data-blocked]{display:none}table{max-width:100% !important}pre{white-space:pre-wrap}
        a{color:#0A64D6}.ce-print{display:none}
        blockquote[type=cite]{margin:0 0 0 .8ex;border-left:2px solid #0A84FF;padding-left:1ex;color:#555}
      </style></head><body>${html}</body></html>`;
      document.body.appendChild(fr);
      try {
        await new Promise((res) => { fr.onload = res; setTimeout(res, 8000); });
        const d = fr.contentDocument, win = fr.contentWindow;
        if (!d?.body) throw new Error('no frame');
        try { await Promise.race([d.fonts?.ready, new Promise(r => setTimeout(r, 4000))]); } catch (e) { /* */ }
        await Promise.race([
          Promise.all([...d.images].map(im => im.complete ? 0 : new Promise(r => { im.onload = im.onerror = r; }))),
          new Promise(r => setTimeout(r, 8000)),
        ]);
        const fullH = Math.max(Math.ceil(d.body.getBoundingClientRect().height), 1);
        fr.style.height = `${fullH + 20}px`;
        await new Promise(r => setTimeout(r, 50));
        const base = doc.getCurrentPageInfo().pageNumber;
        const first = (H - M - y) / scale;            // email pixels that fit on this page
        const per = (H - 2 * M) / scale;              // and on each page after
        const startY = y;
        const pageOf = (top) => (top < first ? 0 : 1 + Math.floor((top - first) / per));
        const pageTop = (p) => (p === 0 ? 0 : first + (p - 1) * per);   // email pixel at the top of page p
        const go = (p) => { while (doc.getNumberOfPages() < base + p) doc.addPage(); doc.setPage(base + p); };
        const yOn = (p, top) => (p === 0 ? startY : M) + (top - pageTop(p)) * scale;
        const X = (left) => M + left * scale;
        // a box, split across pages
        const box = (r, fn) => {
          let top = r.top;
          const bottom = r.top + r.height;
          while (top < bottom - 0.5) {
            const p = pageOf(top);
            const end = Math.min(bottom, pageTop(p + 1));
            go(p);
            fn(X(r.left), yOn(p, top), r.width * scale, (end - top) * scale, top === r.top && end === bottom);
            top = end;
          }
        };
        const imgData = (im) => {
          const cv = document.createElement('canvas');
          const sc = Math.min(1, 1600 / Math.max(im.naturalWidth, 1));
          cv.width = Math.max(1, Math.round(im.naturalWidth * sc)); cv.height = Math.max(1, Math.round(im.naturalHeight * sc));
          const g = cv.getContext('2d');
          g.drawImage(im, 0, 0, cv.width, cv.height);
          return cv.width * cv.height < 250000 ? { url: cv.toDataURL('image/png'), kind: 'PNG' } : (() => {
            const c2 = document.createElement('canvas'); c2.width = cv.width; c2.height = cv.height;
            const g2 = c2.getContext('2d'); g2.fillStyle = '#fff'; g2.fillRect(0, 0, c2.width, c2.height); g2.drawImage(cv, 0, 0);
            return { url: c2.toDataURL('image/jpeg', 0.88), kind: 'JPEG' };
          })();
        };
        const hiddenEl = (el, cs) => cs.display === 'none' || cs.visibility === 'hidden' || parseFloat(cs.opacity) < 0.05;
        const words = [];
        const walker = d.createTreeWalker(d.body, NodeFilter.SHOW_ELEMENT | NodeFilter.SHOW_TEXT, {
          acceptNode: (n) => {
            if (n.nodeType === 1) { const cs = win.getComputedStyle(n); return hiddenEl(n, cs) ? NodeFilter.FILTER_REJECT : NodeFilter.FILTER_ACCEPT; }
            return /\S/.test(n.nodeValue || '') ? NodeFilter.FILTER_ACCEPT : NodeFilter.FILTER_SKIP;
          },
        });
        const range = d.createRange();
        let pics = 0;
        const totalPics = d.images.length;
        for (let n = walker.nextNode(); n; n = walker.nextNode()) {
          if (closed()) return null;
          if (n.nodeType === 1) {
            const el = n, cs = win.getComputedStyle(el);
            const r = el.getBoundingClientRect();
            if (r.width < 0.5 || r.height < 0.5) continue;
            const bg = rgba(cs.backgroundColor);
            const rad = Math.min(parseFloat(cs.borderTopLeftRadius) || 0, r.height / 2, r.width / 2) * scale;
            const sides = ['Top', 'Right', 'Bottom', 'Left'].map(s => ({ w: parseFloat(cs[`border${s}Width`]) || 0, st: cs[`border${s}Style`], c: rgba(cs[`border${s}Color`]) }))
              .map(b => (b.w > 0 && b.st !== 'none' && b.st !== 'hidden' && b.c ? b : null));
            const even = sides.every(s => s && s.w === sides[0].w && s.c.join() === sides[0].c.join());
            if (bg && !(bg[0] > 250 && bg[1] > 250 && bg[2] > 250 && el === d.body)) {
              box(r, (x, yy, w, h, whole) => { doc.setFillColor(bg[0], bg[1], bg[2]); if (rad > 0.5 && whole) doc.roundedRect(x, yy, w, h, rad, rad, 'F'); else doc.rect(x, yy, w, h, 'F'); });
            }
            if (even && rad > 0.5) {
              box(r, (x, yy, w, h, whole) => { doc.setDrawColor(...sides[0].c); doc.setLineWidth(sides[0].w * scale); if (whole) doc.roundedRect(x, yy, w, h, rad, rad, 'S'); else doc.rect(x, yy, w, h, 'S'); });
            } else {
              sides.forEach((b, i) => {
                if (!b) return;
                const lw = b.w * scale;
                const seg = i === 0 ? { left: r.left, top: r.top, width: r.width, height: b.w } : i === 2 ? { left: r.left, top: r.bottom - b.w, width: r.width, height: b.w }
                  : i === 1 ? { left: r.right - b.w, top: r.top, width: b.w, height: r.height } : { left: r.left, top: r.top, width: b.w, height: r.height };
                box(seg, (x, yy, w, h) => { doc.setFillColor(...b.c); doc.rect(x, yy, Math.max(w, lw * 0.5), Math.max(h, lw * 0.5), 'F'); });
              });
            }
            // list bullets and numbers (the browser draws these itself, so they aren't in the text)
            if (cs.display === 'list-item' && cs.listStyleType !== 'none') {
              range.selectNodeContents(el);
              const fr0 = [...range.getClientRects()].find(q => q.width > 0.2 && q.height > 0.2);
              if (fr0) {
                const p = pageOf(fr0.top); go(p);
                const fpx = parseFloat(cs.fontSize) || 15, col = rgba(cs.color) || [17, 17, 17];
                const cy = yOn(p, fr0.top) + fr0.height * scale / 2;
                const lt = cs.listStyleType;
                if (/^(disc|circle|square)$/.test(lt)) {
                  doc.setFillColor(...col); doc.setDrawColor(...col); doc.setLineWidth(0.6);
                  const rr = fpx * scale * 0.16, cx = X(r.left) - fpx * scale * 0.75;
                  if (lt === 'square') doc.rect(cx - rr, cy - rr, rr * 2, rr * 2, 'F'); else doc.circle(cx, cy, rr, lt === 'circle' ? 'S' : 'F');
                } else {
                  const lis = [...el.parentElement.children].filter(c => c.tagName === 'LI');
                  const num = (parseInt(el.parentElement.getAttribute('start'), 10) || 1) + lis.indexOf(el);
                  const label = lt === 'lower-alpha' || lt === 'lower-latin' ? String.fromCharCode(96 + num) : lt === 'upper-alpha' || lt === 'upper-latin' ? String.fromCharCode(64 + num) : String(num);
                  setFont(fpx * scale); doc.setTextColor(...col);
                  doc.text(`${label}.`, X(r.left) - fpx * scale * 0.4, cy + fpx * scale * 0.35, { align: 'right' });
                }
              }
            }
            if (el.tagName === 'IMG' && el.naturalWidth > 3 && el.naturalHeight > 3) {
              status('Adding pictures', ++pics, totalPics);
              try {
                const im = imgData(el);
                const p = pageOf(r.top);
                go(p);
                doc.addImage(im.url, im.kind, X(r.left), yOn(p, r.top), r.width * scale, r.height * scale);
                const a = el.closest('a[href]');
                if (a && /^(https?:|mailto:|tel:)/i.test(a.getAttribute('href'))) doc.link(X(r.left), yOn(p, r.top), r.width * scale, r.height * scale, { url: a.getAttribute('href') });
              } catch (e) { /* a picture the browser won't share: left out */ }
            }
            continue;
          }
          // the words of a text node, each where the browser put it
          const parent = n.parentElement;
          if (!parent) continue;
          const cs = win.getComputedStyle(parent);
          const col = rgba(cs.color) || [17, 17, 17];
          const px = parseFloat(cs.fontSize) || 15;
          const bold = (parseInt(cs.fontWeight, 10) || 400) >= 600;
          const italic = /italic|oblique/.test(cs.fontStyle);
          const tt = cs.textTransform;
          const a = parent.closest('a[href]');
          const href = a && /^(https?:|mailto:|tel:)/i.test(a.getAttribute('href')) ? a.getAttribute('href') : null;
          const deco = /underline/.test(cs.textDecorationLine || cs.textDecoration || '');
          const text = n.nodeValue;
          const re = /\S+/g;
          let mt;
          while ((mt = re.exec(text))) {
            let w = mt[0];
            range.setStart(n, mt.index); range.setEnd(n, mt.index + w.length);
            const rects = [...range.getClientRects()].filter(q => q.width > 0.2);
            if (!rects.length) continue;
            if (tt === 'uppercase') w = w.toUpperCase(); else if (tt === 'lowercase') w = w.toLowerCase(); else if (tt === 'capitalize') w = w.charAt(0).toUpperCase() + w.slice(1);
            if (rects.length === 1) { words.push({ t: w, r: rects[0], col, px, bold, italic, href, deco }); continue; }
            // a long word (a web address) broken over lines: one piece per line
            let piece = '', pr = null;
            for (let i = 0; i < mt[0].length; i++) {
              range.setStart(n, mt.index + i); range.setEnd(n, mt.index + i + 1);
              const q = range.getBoundingClientRect();
              if (pr && Math.abs(q.top - pr.top) > 2) { words.push({ t: piece, r: pr, col, px, bold, italic, href, deco }); piece = ''; pr = null; }
              piece += w[i] || mt[0][i];
              pr = pr ? { left: pr.left, top: pr.top, width: q.right - pr.left, height: Math.max(pr.height, q.height), bottom: Math.max(pr.bottom, q.bottom), right: q.right } : { left: q.left, top: q.top, width: q.width, height: q.height, bottom: q.bottom, right: q.right };
            }
            if (piece && pr) words.push({ t: piece, r: pr, col, px, bold, italic, href, deco });
          }
        }
        // the words go on top of the boxes and pictures
        for (let wi = 0; wi < words.length; wi++) {
          const wd = words[wi], r = wd.r, p = pageOf(r.top);
          const nx = words[wi + 1];
          // an underline runs on under the space to the next underlined word on the same line
          const ulW = nx && nx.deco && wd.deco && Math.abs(nx.r.top - r.top) < 2 && nx.r.left > r.left && nx.href === wd.href ? (nx.r.left - r.left) * scale : null;
          go(p);
          const size = wd.px * scale;
          const x = X(r.left), top = yOn(p, r.top), wpt = r.width * scale;
          const baseline = top + (r.height * scale) / 2 + size * 0.35;
          const t = clean(wd.t);
          if (!t) continue;
          if (PDF_IMG_RUN.test(t)) {
            PDF_IMG_RUN.lastIndex = 0;
            const im = runImage(wd.t, size, `rgb(${wd.col.join(',')})`);
            const h = Math.min(im.h, r.height * scale * 1.1), w = im.w * h / im.h;
            doc.addImage(im.url, 'PNG', x, top + (r.height * scale - h) / 2, Math.min(w, wpt * 1.05), h);
          } else {
            setFont(size, { bold: wd.bold, italic: wd.italic });
            const nat = doc.getTextWidth(t);
            // the PDF's font is a little wider or narrower than the phone's: fit it to the word's space
            const fit = nat > wpt * 1.02 ? size * (wpt / nat) : size;
            if (fit !== size) doc.setFontSize(fit);
            doc.setTextColor(wd.col[0], wd.col[1], wd.col[2]);
            doc.text(t, x, baseline);
            if (wd.deco) { doc.setDrawColor(...wd.col); doc.setLineWidth(Math.max(0.4, size / 18)); doc.line(x, baseline + size * 0.12, x + (ulW || Math.min(nat, wpt)), baseline + size * 0.12); }
          }
          PDF_IMG_RUN.lastIndex = 0;
          if (wd.href) doc.link(x, top, wpt, r.height * scale, { url: wd.href });
        }
        const endP = pageOf(fullH);
        go(endP);
        y = yOn(endP, fullH) + 4;
        return true;
      } finally { fr.remove(); }
    };

    const list = (arr) => (arr || []).map(p => p.name ? `${p.name} <${p.email}>` : p.email).join(', ');

    // the subject at the top
    text(msgs[0]?.subject || '(No subject)', 18, { bold: true });
    if (conversation) { y += 2; text(`${msgs.length} email${msgs.length === 1 ? '' : 's'} in this conversation`, 10, {}, [110, 110, 115]); }
    y += 6;
    for (let i = 0; i < msgs.length; i++) {
      if (closed()) return null;
      status(msgs.length > 1 ? 'Writing email' : 'Writing the email…', ...(msgs.length > 1 ? [i + 1, msgs.length] : []));
      const m = msgs[i];
      ensure(70);
      doc.setDrawColor(209, 209, 214); doc.setLineWidth(0.6); doc.line(M, y, W - M, y);
      y += 10;
      text(list((m.from || []).slice(0, 1)) || '(Unknown sender)', 11.5, { bold: true });
      text(`To: ${list(m.to) || '—'}`, 9.5, {}, [90, 90, 95]);
      if ((m.cc || []).length) text(`Cc: ${list(m.cc)}`, 9.5, {}, [90, 90, 95]);
      text(fmtFull(m.date, this._hass), 9.5, {}, [90, 90, 95]);
      y += 10;
      let html = m.html_safe || '';
      if (conversation) html = html.replace(/<blockquote[\s\S]*<\/blockquote>/i, '');
      let drawn = false;
      try { drawn = await renderDom(html, proxied); } catch (e) { console.warn('Crow Messenger Email PDF: drawing it as text instead', e); drawn = false; }
      if (drawn === null) return null;
      const blocks = drawn ? [] : this._pdfBlocks(html);
      let n = 0;
      for (const b of blocks) {
        if (closed()) return null;
        if (b.type === 'img') { status('Adding pictures', ++n, blocks.filter(x => x.type === 'img').length); await picture(b); continue; }
        if (b.type === 'hr') { ensure(12); doc.setDrawColor(209, 209, 214); doc.setLineWidth(0.6); doc.line(M + b.indent, y + 5, W - M, y + 5); y += 12; continue; }
        if (b.type === 'button') { y += 2; button(b); continue; }
        const x = M + b.indent, maxW = W - M - x;
        const lines = layout(b.runs, maxW, b.pre);
        drawLines(lines, x, maxW, { quote: b.quote, align: b.align });
        y += (lines[lines.length - 1]?.size || BASE) * 0.6;
      }
      const atts = (m.attachments || []).filter(a => !a.inline);
      if (atts.length) { y += 4; text(`Attachments: ${atts.map(a => a.name).join(', ')}`, 9.5, { italic: true }, [90, 90, 95]); }
      y += 14;
    }
    // page numbers
    const pages = doc.getNumberOfPages();
    if (pages > 1) {
      for (let i = 1; i <= pages; i++) {
        doc.setPage(i); setFont(8.5); doc.setTextColor(140, 140, 145);
        doc.text(`${i} of ${pages}`, W / 2, H - 20, { align: 'center' });
      }
    }
    return doc;
  },

  _ensurePdfJs() {
    if (window.pdfjsLib?.getDocument) return Promise.resolve(window.pdfjsLib);
    if (this._pdfJsLoadPromise) return this._pdfJsLoadPromise;
    const BASE = 'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/';
    this._pdfJsLoadPromise = new Promise((resolve, reject) => {
      const script = document.createElement('script');
      script.src = BASE + 'pdf.min.js';
      const fail = (msg) => { this._pdfJsLoadPromise = null; reject(new Error(msg)); };
      const t = setTimeout(() => fail('PDF viewer took too long to load'), 15000);
      script.onload = () => {
        clearTimeout(t);
        const lib = window.pdfjsLib;
        if (!lib?.getDocument) { fail('PDF viewer failed to initialise'); return; }
        lib.GlobalWorkerOptions.workerSrc = BASE + 'pdf.worker.min.js';
        resolve(lib);
      };
      script.onerror = () => { clearTimeout(t); fail('Could not load the PDF viewer'); };
      document.head.appendChild(script);
    });
    return this._pdfJsLoadPromise;
  },

  // Draws every page of the PDF into the preview as a scrolling stack, with
  // a "Page 2 of 5" counter. Pages are only drawn as they scroll near, and
  // each one is kept as an image (not a live canvas) so long PDFs don't run
  // the phone out of memory. Pinch to zoom (up to 4x) or double-tap to zoom
  // in and back out; pages are redrawn sharper once a zoom settles.
  async _renderPDFPages(frameWrap, buf, { isClosed = () => false, onCleanup = () => {} } = {}) {
    const lib = await this._ensurePdfJs();
    if (isClosed()) return;
    const pdf = await lib.getDocument({ data: new Uint8Array(buf) }).promise;
    onCleanup(() => pdf.destroy());
    if (isClosed()) return;
    const total = pdf.numPages;
    const first = await pdf.getPage(1);
    const vp1 = first.getViewport({ scale: 1 });
    if (isClosed()) return;

    frameWrap.innerHTML = '';
    frameWrap.style.display = 'block';
    frameWrap.style.position = 'relative';
    frameWrap.style.background = '#d1d1d6';
    const scroller = document.createElement('div');
    scroller.style.cssText = 'position:absolute;inset:0;overflow:auto;-webkit-overflow-scrolling:touch;padding:10px;box-sizing:border-box;touch-action:pan-x pan-y;';
    frameWrap.appendChild(scroller);
    // The zoomable sheet holding the pages — zoom is its width
    const sheet = document.createElement('div');
    sheet.style.cssText = 'width:100%;transform-origin:0 0;';
    scroller.appendChild(sheet);
    const counter = document.createElement('div');
    counter.style.cssText = 'position:absolute;bottom:10px;left:50%;transform:translateX(-50%);background:rgba(0,0,0,0.62);color:#fff;font-size:11px;font-weight:600;padding:4px 11px;border-radius:11px;pointer-events:none;white-space:nowrap;' + (total > 1 ? '' : 'display:none;');
    frameWrap.appendChild(counter);
    const GAP = 10;

    const holders = [];
    for (let i = 1; i <= total; i++) {
      const h = document.createElement('div');
      h.dataset.page = String(i);
      h.style.cssText = 'position:relative;width:100%;aspect-ratio:' + vp1.width + ' / ' + vp1.height + ';background:#fff;border-radius:3px;box-shadow:0 1px 4px rgba(0,0,0,0.18);overflow:hidden;' + (i < total ? 'margin-bottom:' + GAP + 'px;' : '');
      sheet.appendChild(h);
      holders.push(h);
    }

    const urls = new Set();
    onCleanup(() => urls.forEach(u => URL.revokeObjectURL(u)));
    const MAX_PX = 2600;            // widest a page is ever drawn (memory)
    const drawnW = new Map();       // page -> pixel width it was drawn at
    const busy = new Set();
    let chain = Promise.resolve();
    const wantPx = (holder) => {
      const dpr = Math.min(window.devicePixelRatio || 1, 2.5);
      return Math.min(MAX_PX, Math.round((holder.clientWidth || scroller.clientWidth - 20 || 320) * dpr));
    };
    const renderPage = (n) => {
      const holder = holders[n - 1];
      if (!holder || busy.has(n)) return;
      const target = wantPx(holder);
      if ((drawnW.get(n) || 0) >= target * 0.9) return;   // already sharp enough
      busy.add(n);
      chain = chain.then(async () => {
        if (isClosed()) return;
        const page = n === 1 ? first : await pdf.getPage(n);
        const base = page.getViewport({ scale: 1 });
        const px = wantPx(holder);
        const viewport = page.getViewport({ scale: px / base.width });
        const canvas = document.createElement('canvas');
        canvas.width = Math.floor(viewport.width);
        canvas.height = Math.floor(viewport.height);
        await page.render({ canvasContext: canvas.getContext('2d'), viewport }).promise;
        if (n !== 1) page.cleanup();
        if (isClosed()) return;
        const blob = await new Promise(res => canvas.toBlob(res, 'image/png'));
        canvas.width = 0; canvas.height = 0;   // free the canvas memory
        if (!blob || isClosed()) return;
        const url = URL.createObjectURL(blob);
        urls.add(url);
        const old = holder.querySelector('img');
        const img = document.createElement('img');
        img.alt = 'Page ' + n;
        img.draggable = false;
        img.style.cssText = 'display:block;width:100%;height:100%;position:absolute;inset:0;';
        img.onload = () => {
          if (old) { const ou = old.src; old.remove(); if (urls.has(ou)) { URL.revokeObjectURL(ou); urls.delete(ou); } }
        };
        img.src = url;
        holder.appendChild(img);
        drawnW.set(n, canvas.width || px);
      }).catch(() => {}).finally(() => { busy.delete(n); });
    };
    const visiblePages = (margin = 0) => {
      const top = scroller.scrollTop - margin, bottom = scroller.scrollTop + scroller.clientHeight + margin;
      return holders.filter(h => h.offsetTop + h.offsetHeight >= top && h.offsetTop <= bottom).map(h => Number(h.dataset.page));
    };

    // Draw pages as they come near the visible area
    if ('IntersectionObserver' in window) {
      const io = new IntersectionObserver(entries => {
        entries.forEach(en => { if (en.isIntersecting) renderPage(Number(en.target.dataset.page)); });
      }, { root: scroller, rootMargin: '900px 300px' });
      holders.forEach(h => io.observe(h));
      onCleanup(() => io.disconnect());
    } else {
      for (let i = 1; i <= total; i++) renderPage(i);
    }
    renderPage(1);

    const updateCounter = () => {
      const mid = scroller.scrollTop + scroller.clientHeight / 2;
      let cur = 1;
      for (const h of holders) { if (h.offsetTop <= mid) cur = Number(h.dataset.page); else break; }
      counter.textContent = 'Page ' + cur + ' of ' + total;
    };
    scroller.addEventListener('scroll', updateCounter, { passive: true });
    updateCounter();

    // ── Zoom ──
    const MIN_Z = 1, MAX_Z = 4;
    let zoom = 1;
    let sharpenTimer = null;
    const sharpen = () => {
      clearTimeout(sharpenTimer);
      sharpenTimer = setTimeout(() => { if (!isClosed()) visiblePages(200).forEach(renderPage); }, 250);
    };
    // Set the zoom, keeping the content point under (cx, cy) — coordinates
    // relative to the scroller's visible box — where it is.
    const setZoom = (z, cx, cy) => {
      z = Math.max(MIN_Z, Math.min(MAX_Z, z));
      const pad = 10;
      const ratio = z / zoom;
      const contentX = scroller.scrollLeft + cx - pad;
      const contentY = scroller.scrollTop + cy - pad;
      // Page gaps don't scale, so vertical position is mapped page by page
      const pageIdx = Math.max(0, Math.min(total - 1, Math.floor(contentY / (holders[0].offsetHeight + GAP))));
      const gapsAbove = pageIdx * GAP;
      zoom = z;
      sheet.style.width = (z * 100) + '%';
      scroller.scrollLeft = contentX * ratio - cx + pad;
      scroller.scrollTop = (contentY - gapsAbove) * ratio + gapsAbove - cy + pad;
      updateCounter();
      sharpen();
    };

    const dist = (t) => Math.hypot(t[0].clientX - t[1].clientX, t[0].clientY - t[1].clientY);
    const rel = (x, y) => { const r = scroller.getBoundingClientRect(); return [x - r.left, y - r.top]; };
    let pinch = null;          // { d0, z0, cx, cy, scale }
    let lastTap = 0;
    const onStart = (e) => {
      if (e.touches.length === 2) {
        const [cx, cy] = rel((e.touches[0].clientX + e.touches[1].clientX) / 2, (e.touches[0].clientY + e.touches[1].clientY) / 2);
        // Live preview with a transform (smooth), committed on release
        const ox = scroller.scrollLeft + cx - 10, oy = scroller.scrollTop + cy - 10;
        sheet.style.transformOrigin = ox + 'px ' + oy + 'px';
        pinch = { d0: dist(e.touches), z0: zoom, cx, cy, scale: 1 };
        e.preventDefault();
      } else if (e.touches.length === 1) {
        const now = Date.now();
        if (now - lastTap < 300) {
          const [cx, cy] = rel(e.touches[0].clientX, e.touches[0].clientY);
          setZoom(zoom > 1.05 ? 1 : 2.5, cx, cy);
          lastTap = 0;
          e.preventDefault();
        } else lastTap = now;
      }
    };
    const onMove = (e) => {
      if (!pinch || e.touches.length < 2) return;
      e.preventDefault();
      const z = Math.max(MIN_Z, Math.min(MAX_Z, pinch.z0 * dist(e.touches) / pinch.d0));
      pinch.scale = z / pinch.z0;
      sheet.style.transform = 'scale(' + pinch.scale + ')';
    };
    const onEnd = (e) => {
      if (!pinch || e.touches.length >= 2) return;
      const { z0, scale, cx, cy } = pinch;
      pinch = null;
      sheet.style.transform = '';
      sheet.style.transformOrigin = '0 0';
      if (Math.abs(scale - 1) > 0.01) setZoom(z0 * scale, cx, cy);
    };
    scroller.addEventListener('touchstart', onStart, { passive: false });
    scroller.addEventListener('touchmove', e => { onMove(e); e.stopPropagation(); }, { passive: false });
    scroller.addEventListener('touchend', onEnd);
    scroller.addEventListener('touchcancel', onEnd);
    // Safari's own page-zoom gesture would zoom the whole dashboard instead
    ['gesturestart', 'gesturechange'].forEach(ev => scroller.addEventListener(ev, e => e.preventDefault(), { passive: false }));
    // Ctrl/trackpad pinch on a computer
    scroller.addEventListener('wheel', (e) => {
      if (!e.ctrlKey) return;
      e.preventDefault();
      const [cx, cy] = rel(e.clientX, e.clientY);
      setZoom(zoom * Math.exp(-e.deltaY / 200), cx, cy);
    }, { passive: false });
    scroller.addEventListener('dblclick', (e) => {
      const [cx, cy] = rel(e.clientX, e.clientY);
      setZoom(zoom > 1.05 ? 1 : 2.5, cx, cy);
    });
  },

  _pdfName(subject) { return `${String(subject || 'Email').replace(/[\\/:*?"<>|]+/g, '').replace(/\s+/g, ' ').trim().slice(0, 80) || 'Email'}.pdf`; },
});

