// Household settings changed in the editor wait in the browser until the dashboard's Save
// button is pressed. The card's config gets a short change id
// (household_changes) so Home Assistant sees a change and Save lights up. When the dashboard
// is saved and the saved config holds that id, the waiting changes are sent; Cancel never
// saves the id, so nothing is sent.
const CE_HC = 'household_changes';
const CE_STAGED = new Map();   // change id -> settings patch
const CE_WATCH = { unsub: null, hass: null };
const ceMerge = (a, b) => {
  const out = { ...(a || {}) };
  Object.entries(b || {}).forEach(([k, v]) => {
    out[k] = v && typeof v === 'object' && !Array.isArray(v) && out[k] && typeof out[k] === 'object' && !Array.isArray(out[k]) ? ceMerge(out[k], v) : v;
  });
  return out;
};
const ceApplySaved = async (hass, urlPath) => {
  if (!CE_STAGED.size) return;
  let cfg;
  try { cfg = await hass.callWS({ type: 'lovelace/config', url_path: urlPath ?? null }); } catch (e) { return; }
  let patch = null;
  const walk = (n) => {
    if (Array.isArray(n)) { n.forEach(walk); return; }
    if (!n || typeof n !== 'object') return;
    const id = n[CE_HC];
    if (typeof id === 'string' && CE_STAGED.has(id)) { patch = ceMerge(patch, CE_STAGED.get(id)); CE_STAGED.delete(id); }
    Object.values(n).forEach(walk);
  };
  walk(cfg);
  if (!patch) return;
  try { await hass.callWS({ type: `${DOMAIN}/settings/save`, ...patch }); }
  catch (e) { console.warn('Crow Messenger Email: couldn’t save household settings', e); }
};
const ceWatch = (hass) => {
  CE_WATCH.hass = hass;
  if (CE_WATCH.unsub) return;
  CE_WATCH.unsub = hass.connection.subscribeEvents((ev) => ceApplySaved(CE_WATCH.hass, ev?.data?.url_path), 'lovelace_updated')
    .catch(e => { console.warn('Crow Messenger Email: can’t watch for Save', e); CE_WATCH.unsub = null; return null; });
};

