Object.assign(CrowMessengerEmail.prototype, {
  _feat(name) { return this._config[name] === true; },

  // ── Snooze ──────────────────────────────────────────────────────────
  async _snoozeItem(it, { then } = {}) {
    const suggest = this._s.ai?.smart_snooze ? this._call('ai/snooze', { account: it.account, folder: it.folder, uid: it.uid }).then(r => r.times) : null;
    const ts = await this._pickTime('Snooze Until', 'Snooze', { suggest });
    if (!ts) return false;
    try {
      await this._call('snooze', { account: it.account, folder: it.folder, uid: it.uid, until: ts });
      this._toast(`Snoozed until ${fmtWhen(ts, this._hass).replace(/^Today/, 'today').replace(/^Tomorrow/, 'tomorrow')}`);
      then?.();
      return true;
    } catch (err) { this._err(err); return false; }
  },

  async _openSnoozed(sid) {
    try { const at = await this._call('snooze/locate', { id: sid }); this._nav('reader', { ...at }); } catch (err) { this._err(err); }
  },

  _pg_snoozed() {
    const el = this._simplePage('Snoozed', '<div class="body"></div>');
    this._scrollTitle(el);
    const body = el.querySelector('.body');
    const draw = () => {
      const list = [...(this._s.snoozed || [])].sort((a, b) => a.until - b.until);
      body.innerHTML = list.length ? `<div class="sgroup">${list.map(s => `<div class="gr" role="button" data-id="${esc(s.id)}"><span class="gi" style="background:#5856D6">${ICON.snooze}</span><span class="gl">${esc(s.subject || '(No subject)')}<small>${esc(whoShort((s.from || [])[0]))} · ${s.home ? 'back when you get home' : `back ${esc(fmtWhen(s.until, this._hass))}`}</small></span><span class="gch">${ICON.chevR}</span></div>`).join('')}</div>
        <div class="sfoot">Snoozed emails wait in a Snoozed folder, then come back to the top of your Inbox, unread, with a notification.</div>`
        : '<div class="empty"><b>Nothing Snoozed</b>Choose Snooze on an email to put it away until later. It comes back to the top of your Inbox when its time comes.</div>';
    };
    el.addEventListener('click', async (e) => {
      if (e.target.closest('[data-a="back"]')) { this._back(); return; }
      const row = e.target.closest('[data-id]');
      if (!row) return;
      const s = (this._s.snoozed || []).find(x => x.id === row.dataset.id);
      if (!s) return;
      const v = await this._menu(row, [{ text: 'Open Email', value: 'open', icon: 'mailOpen' }, { text: 'Change Time', value: 'time', icon: 'clock' }, { text: 'Unsnooze Now', value: 'wake', icon: 'inbox' }]);
      try {
        if (v === 'open') this._openSnoozed(s.id);
        if (v === 'wake') { await this._call('snooze/wake', { id: s.id }); this._toast('Back in your Inbox'); }
        if (v === 'time') {
          const ts = await this._pickTime('Snooze Until', 'Snooze');
          if (ts) { const at = await this._call('snooze/locate', { id: s.id }); await this._call('snooze', { ...at, until: ts }); }
        }
      } catch (err) { this._err(err); }
    });
    draw();
    return { el, refresh: (what) => { if (['all', 'snoozed', 'back'].includes(what)) draw(); } };
  },

  // ── Mute Conversation ───────────────────────────────────────────────
  async _muteItem(it, on) {
    try {
      const r = await this._call('mute', { account: it.account, folder: it.folder, uid: it.uid, on });
      this._toast(on ? (r.archived ? 'Conversation muted and archived' : 'Conversation muted') : 'Conversation unmuted');
      return r;
    } catch (err) { this._err(err); return null; }
  },

  _pg_muted() {
    const el = this._simplePage('Muted Conversations', '<div class="body"></div>');
    this._scrollTitle(el);
    const body = el.querySelector('.body');
    const draw = () => {
      const list = [...(this._s.muted || [])].sort((a, b) => b.at - a.at);
      body.innerHTML = list.length ? `<div class="sgroup">${list.map(m => `<div class="gr"><span class="gi" style="background:#636366">${ICON.bellOff}</span><span class="gl">${esc(m.subject || '(No subject)')}<small>${esc(this._acc(m.account)?.name || '')} · muted ${esc(fmtListDate(m.at, this._hass))}</small></span><button class="pill g" data-un="${esc(m.id)}">Unmute</button></div>`).join('')}</div>
        <div class="sfoot">New replies in these conversations skip your Inbox and don’t notify you. They’re archived, so you can still find them.</div>`
        : '<div class="empty"><b>No Muted Conversations</b>Choose Mute Conversation on an email to stop its replies landing in your Inbox.</div>';
    };
    el.addEventListener('click', async (e) => {
      if (e.target.closest('[data-a="back"]')) { this._back(); return; }
      const b = e.target.closest('[data-un]');
      if (b) { try { await this._call('mute', { id: b.dataset.un, on: false }); this._toast('Conversation unmuted'); } catch (err) { this._err(err); } }
    });
    draw();
    return { el, refresh: (what) => { if (['all', 'muted', 'back'].includes(what)) draw(); } };
  },

  // ── Sweep ───────────────────────────────────────────────────────────
  _sweepItems(prefix = 'sweep:') {
    return [
      { text: 'Delete All from Sender', value: `${prefix}trash:none`, icon: 'trash', red: true },
      { text: 'Archive All from Sender', value: `${prefix}archive:none`, icon: 'archive' },
      { text: 'Keep Only the Latest', value: `${prefix}trash:latest`, icon: 'mail' },
      { text: 'Delete Ones Over 10 Days Old', value: `${prefix}trash:older10`, icon: 'clock' },
    ];
  },

  async _sweep(account, folder, frm, value) {
    const [, action, keep] = String(value).split(':');
    const e = String(frm?.email || '').toLowerCase();
    if (!e) return null;
    const name = who(frm) || e;
    const what = keep === 'latest' ? `Every email from ${name} in ${this._folderName(account, folder)} except the newest will be ${action === 'archive' ? 'archived' : 'deleted'}.`
      : keep === 'older10' ? `Emails from ${name} in ${this._folderName(account, folder)} that are more than 10 days old will be deleted.`
        : `Every email from ${name} in ${this._folderName(account, folder)} will be ${action === 'archive' ? 'archived' : 'deleted'}.`;
    const title = action === 'archive' ? 'Archive All?' : keep === 'none' ? 'Delete All?' : 'Sweep?';
    if (!(await this._confirm(title, what, action === 'archive' ? 'Archive' : 'Delete', action !== 'archive'))) return null;
    try {
      const r = await this._call('sweep', { account, folder, email: e, action, keep });
      this._toast(r.count ? `${r.count} email${r.count === 1 ? '' : 's'} ${action === 'archive' ? 'archived' : 'deleted'}` : 'Nothing to sweep');
      this._refresh('mail', { account, folder });
      return r;
    } catch (err) { this._err(err); return null; }
  },

  // ── the Screener ────────────────────────────────────────────────────
  _screenerWaiting() {
    let n = 0;
    for (const a of this._s.accounts) n += ((this._cachedFolders(a.id) || []).find(f => (f.name || '').toLowerCase() === 'screener')?.total) || 0;
    return n;
  },

  _pg_screener() {
    const el = this._simplePage('Screener', '<div class="body"></div>');
    this._scrollTitle(el);
    const body = el.querySelector('.body');
    let list = null, busy = false, err = '';
    const load = async () => {
      if (!this._s.screener?.on) { list = []; draw(); return; }
      busy = true; draw();
      try { list = await this._call('screener/list'); err = ''; } catch (e) { err = e.message || 'Couldn’t look in the Screener.'; list = []; }
      busy = false; draw();
      // a line from the AI on who each sender seems to be
      if (this._s.ai?.screener_notes && list.length) {
        const want = list.slice(0, 12);
        this._call('ai/screener', { items: want.map(g => ({ account: g.account, folder: g.folder, uid: g.emails[0].uid })) })
          .then(r => { (r.notes || []).forEach((n, i) => { if (n && want[i]) want[i].ai = n; }); draw(); }).catch(() => {});
      }
    };
    const KIND = { person: 'Person', shop: 'Shop', service: 'Service', newsletter: 'Newsletter', marketing: 'Marketing', scam: 'Looks Like a Scam' };
    const draw = () => {
      const sc = this._s.screener || {};
      const head = `<div class="sgroup"><div class="gr"><span class="gi" style="background:var(--ce-orange)">${ICON.screener}</span><span class="gl">Screen New Senders<small>The first email from someone new waits here instead of your Inbox, with no notification.</small></span>${this._sw('f-scr', !!sc.on)}</div>
        ${sc.on && this._s.ai?.screener_notes ? `<div class="gr"><span class="gl">Screen Out Marketing Automatically<small>The AI moves obvious marketing from new senders straight to Junk. They aren’t blocked.</small></span>${this._sw('f-scrauto', !!sc.auto_out)}</div>` : ''}
        ${sc.on ? `<div class="gr icon-row" role="button" data-a="allowed"><span class="gl">Let In Automatically</span><span class="gv">${(sc.allowed || []).length || ''}</span><span class="gch">${ICON.chevR}</span></div>` : ''}</div>
        <div class="sfoot">Your contacts, VIPs, safe senders and anyone you’ve emailed always go straight to your Inbox.${sc.on ? '' : ' Turning it on looks through your Sent email first, so only strangers are held.'}</div>`;
      if (!sc.on) { body.innerHTML = head; return; }
      let waiting;
      if (busy && !list) waiting = '<div class="spin"></div>';
      else if (err) waiting = `<div class="list-err">${esc(err)}</div>`;
      else if (!list?.length) waiting = '<div class="empty" style="padding-top:30px"><b>No One Waiting</b>When someone new emails you, you’ll decide here whether they get into your Inbox.</div>';
      else {
        waiting = `<div class="sh" style="margin:18px 16px 8px">Waiting · ${list.length}</div>` + list.map((g, i) => `<div class="scr-card">
          <div class="scr-who">${this._avatar({ name: g.name, email: g.email }, 36)}<span class="nm">${esc(g.name || g.email)}${g.ai ? `<span class="scr-tag ${esc(g.ai.kind)}">${esc(KIND[g.ai.kind] || g.ai.kind)}</span>` : ''}<small>${esc(g.email)}${this._multi() ? ` · ${esc(this._acc(g.account)?.name || '')}` : ''} · ${g.count} email${g.count === 1 ? '' : 's'}</small></span></div>
          ${g.ai?.note ? `<div class="ai-note">${ICON.sparkle}<span>${esc(g.ai.note)}</span></div>` : ''}
          <div class="scr-mail">${g.emails.slice(0, 3).map(m => `<button data-open="${i}:${m.uid}">${esc(m.subject || '(No subject)')}<small>${esc(fmtListDate(m.date, this._hass))}</small></button>`).join('')}</div>
          <div class="scr-btns"><button class="yes${g.ai?.suggest === 'let_in' ? ' sugg' : ''}" data-yes="${i}">Let In</button><button class="no${g.ai?.suggest === 'screen_out' ? ' sugg' : ''}" data-no="${i}">Screen Out</button></div></div>`).join('')
          + `<div class="sfoot">Screen Out blocks the sender (undo it in Blocked Senders). Their emails go to Junk.${list.some(g => g.ai) ? ' The outlined button is what the AI suggests.' : ''}</div>`;
      }
      body.innerHTML = head + waiting;
    };
    el.addEventListener('change', async (e) => {
      if (e.target.classList.contains('f-scrauto')) {
        try { this._s.screener = await this._call('screener/set', { auto_out: e.target.checked }); } catch (err2) { this._err(err2); }
        draw();
        return;
      }
      if (!e.target.classList.contains('f-scr')) return;
      const on = e.target.checked;
      busy = true; list = null; draw();
      try { this._s.screener = await this._call('screener/set', { on }); this._toast(on ? 'Screener on' : 'Screener off'); } catch (err2) { this._err(err2); }
      busy = false; load();
    });
    el.addEventListener('click', async (e) => {
      if (e.target.closest('[data-a="back"]')) { this._back(); return; }
      if (e.target.closest('[data-a="allowed"]')) { this._nav('screenerallowed'); return; }
      const o = e.target.closest('[data-open]');
      if (o) { const [i, uid] = o.dataset.open.split(':'); const g = list[+i]; this._nav('reader', { account: g.account, folder: g.folder, uid: +uid }); return; }
      const y = e.target.closest('[data-yes],[data-no]');
      if (!y) return;
      const allow = !!y.dataset.yes, g = list[+(y.dataset.yes ?? y.dataset.no)];
      if (!allow && !(await this._confirm('Screen Out?', `${g.name || g.email} will be blocked and their emails moved to Junk. You can undo this in Blocked Senders.`, 'Screen Out', true))) return;
      y.closest('.scr-card').querySelectorAll('button').forEach(b => { b.disabled = true; });
      try {
        await this._call('screener/decide', { account: g.account, email: g.email, allow });
        this._toast(allow ? `${g.name || g.email} is in your Inbox now` : `${g.name || g.email} screened out`);
        list = list.filter(x => x !== g); draw();
        this._foldersFor(g.account, true).then(() => this._refresh('counts', g.account)).catch(() => {});
      } catch (err2) { this._err(err2); draw(); }
    });
    load();
    return { el, refresh: (what) => { if (what === 'screener' || what === 'back') load(); } };
  },

  _pg_screenerallowed() {
    const el = this._simplePage('Let In Automatically', '<div class="body"></div>');
    this._scrollTitle(el);
    const body = el.querySelector('.body');
    const draw = () => {
      const list = [...(this._s.screener?.allowed || [])].sort();
      body.innerHTML = list.length ? `<div class="sgroup">${list.map((x, i) => `<div class="gr trust-row"><span class="gl">${esc(x)}</span><button class="pc-more" data-rm="${i}" aria-label="Remove" style="color:var(--ce-red)">${ICON.trash}</button></div>`).join('')}</div>
        <div class="sfoot">People you’ve let in, or emailed. Remove someone to screen them again.</div>`
        : '<div class="empty"><b>No One Yet</b>People you let in, or email, are added here.</div>';
      body._list = list;
    };
    el.addEventListener('click', async (e) => {
      if (e.target.closest('[data-a="back"]')) { this._back(); return; }
      const rm = e.target.closest('[data-rm]');
      if (rm) { try { this._s.screener = await this._call('screener/set', { remove: [body._list[+rm.dataset.rm]] }); draw(); } catch (err) { this._err(err); } }
    });
    draw();
    return { el, refresh: (what) => { if (['screener', 'back'].includes(what)) draw(); } };
  },

  // ── Subscriptions ───────────────────────────────────────────────────
  _pg_subscriptions(data = {}) {
    const el = this._simplePage('Subscriptions', '<div class="acc-chips"></div><div class="body"></div>');
    this._scrollTitle(el);
    const body = el.querySelector('.body'), chips = el.querySelector('.acc-chips');
    let account = data.account || this._s.accounts[0]?.id, list = null, err = '', busy = false, bulk = false;
    const never = (g) => g.count >= 3 && g.unread === g.count && !g.unsubscribed && g.list_unsubscribe;
    const load = async (force = false) => {
      if (!account) return;
      busy = true; list = force ? list : null; draw();
      try { list = await this._call('subscriptions', { account, force }); err = ''; } catch (e) { err = e.message || 'Couldn’t look through your Inbox.'; list = []; }
      busy = false; draw();
      // what each list sends, in a few words (the ones you never read first)
      if (this._s.ai?.sub_notes && list.length) {
        const want = [...list.filter(never), ...list.filter(g => !never(g))].slice(0, 15);
        this._call('ai/subscriptions', { account, items: want.map(g => ({ email: g.email, uid: g.uid })) })
          .then(r => { list.forEach(g => { if (r.notes?.[g.email]) g.note = r.notes[g.email]; }); draw(); }).catch(() => {});
      }
    };
    const freq = (g) => g.per_week >= 6.5 ? 'Daily' : g.per_week >= 1.5 ? `About ${Math.round(g.per_week)} a week` : g.per_week >= 0.9 ? 'Weekly' : 'Now and then';
    const row = (g) => {
      const i = list.indexOf(g);
      return `<div class="gr">${this._avatar({ name: g.name, email: g.email }, 32)}<span class="gl">${esc(g.name || g.email)}<small>${g.count} in your Inbox · ${esc(freq(g))}${g.unread === g.count && g.count >= 3 ? ' · never opened' : ''}</small>${g.note ? `<span class="sub-note">${esc(g.note)}</span>` : ''}</span>
        ${g.unsubscribed ? '<span class="sub-tag">Unsubscribed</span>' : g.list_unsubscribe ? `<button class="pill g subs-un" data-un="${i}">Unsubscribe</button>` : ''}<button class="pc-more" data-mo="${i}" aria-label="More">${ICON.more}</button></div>`;
    };
    const draw = () => {
      chips.innerHTML = this._multi() ? this._s.accounts.map(a => `<button class="chip${a.id === account ? ' on' : ''}" data-acc="${esc(a.id)}">${esc(a.name || a.email)}</button>`).join('') : '';
      if (!list) { body.innerHTML = '<div class="spin"></div><div class="sfoot" style="text-align:center">Looking through your Inbox…</div>'; return; }
      if (err) { body.innerHTML = `<div class="list-err">${esc(err)}</div>`; return; }
      if (!list.length) { body.innerHTML = '<div class="empty"><b>No Subscriptions</b>No mailing lists or newsletters in your Inbox.</div>'; return; }
      const nv = list.filter(never), rest = list.filter(g => !never(g));
      body.innerHTML = `<div class="sfoot" style="margin-top:0">Mailing lists and newsletters in your Inbox, busiest first.${busy ? ' <span class="spin small"></span>' : ''}</div>
        ${nv.length ? `<div class="sh" style="display:flex;align-items:center">You Never Read These · ${nv.length}<button class="pill g subs-un" data-a="unall" style="margin-left:auto"${bulk ? ' disabled' : ''}>${bulk ? 'Unsubscribing…' : 'Unsubscribe All'}</button></div><div class="sgroup">${nv.map(row).join('')}</div>` : ''}
        ${rest.length ? `${nv.length ? '<div class="sh" style="margin-top:20px">Everything Else</div>' : ''}<div class="sgroup">${rest.map(row).join('')}</div>` : ''}
        <div class="sfoot">Unsubscribing asks the sender to stop. Some take a few days. Delete All removes their emails from your Inbox.</div>`;
    };
    const unsubOne = async (g) => {
      const r = await this._call('subscriptions/unsubscribe', { account, email: g.email, header: g.list_unsubscribe, one_click: !!g.one_click });
      if (r.how !== 'open') g.unsubscribed = Date.now();
      return r;
    };
    el.addEventListener('click', async (e) => {
      if (e.target.closest('[data-a="back"]')) { this._back(); return; }
      const ch = e.target.closest('[data-acc]');
      if (ch) { account = ch.dataset.acc; load(); return; }
      if (e.target.closest('[data-a="unall"]')) {
        const nv = list.filter(never);
        if (bulk || !nv.length || !(await this._confirm('Unsubscribe from All?', `Stop getting emails from ${nv.length} list${nv.length === 1 ? '' : 's'} you never read?`, 'Unsubscribe All'))) return;
        bulk = true; draw();
        let done = 0, manual = 0;
        for (const g of nv) {
          try { const r = await unsubOne(g); if (r.how === 'open') manual++; else done++; } catch (err2) { manual++; }
          draw();
        }
        bulk = false; draw();
        this._toast(`Unsubscribed from ${done}${manual ? `. ${manual} need finishing on their own page (tap Unsubscribe).` : ''}`);
        return;
      }
      const un = e.target.closest('[data-un]'), mo = e.target.closest('[data-mo]');
      const g = un ? list[+un.dataset.un] : mo ? list[+mo.dataset.mo] : null;
      if (!g) return;
      if (un) {
        if (!(await this._confirm('Unsubscribe?', `Stop getting emails from ${g.name || g.email}?`, 'Unsubscribe'))) return;
        un.disabled = true;
        try {
          const r = await unsubOne(g);
          if (r.how === 'open') { openExternal(r.url); this._toast('Finish unsubscribing on their page'); }
          else this._toast(r.how === 'one_click' ? 'Unsubscribed' : 'Unsubscribe request sent');
          draw();
          if (r.how !== 'open' && g.count > 1 && await this._confirm('Delete Their Emails Too?', `Delete the ${g.count} emails from ${g.name || g.email} in your Inbox?`, 'Delete', true)) {
            const s = await this._call('sweep', { account, folder: 'INBOX', email: g.email, action: 'trash', keep: 'none' });
            this._toast(`${s.count} email${s.count === 1 ? '' : 's'} deleted`);
            list = list.filter(x => x !== g); draw();
          }
        } catch (err2) { this._err(err2); un.disabled = false; }
        return;
      }
      const v = await this._menu(mo, [{ header: g.name || g.email }, { text: 'Open Latest Email', value: 'open', icon: 'mailOpen' }, { sep: true }, ...this._sweepItems()]);
      if (!v) return;
      if (v === 'open') { this._nav('reader', { account, folder: 'INBOX', uid: g.uid }); return; }
      const r = await this._sweep(account, 'INBOX', { name: g.name, email: g.email }, v);
      if (r?.count) load(true);
    });
    load();
    return { el, refresh: (what) => { if (what === 'mail') load(true); } };
  },

  // ── Custom Swipes ───────────────────────────────────────────────────
  _swipes() {
    const std = { right: ['read', 'pin'], left: [this._config.swipe_action === 'trash' ? 'trash' : 'archive', 'flag', 'more'], long_right: 'none', long_left: this._config.swipe_action === 'trash' ? 'trash' : 'archive' };
    if (!this._feat('custom_swipes')) return std;
    const p = this._s.prefs?.swipes || {};
    const ok = (a) => SW_ACTS[a] && (!SW_ACTS[a].needs || this._feat(SW_ACTS[a].needs));
    const right = (p.right || std.right).filter(ok), left = (p.left || std.left).filter(ok);
    return {
      right: right.length ? right : std.right, left: left.length ? left : std.left,
      long_right: ok(p.long_right) ? p.long_right : 'none',
      long_left: p.long_left === 'none' ? 'none' : ok(p.long_left) ? p.long_left : std.long_left,
    };
  },

  _swBtn(it, a) {
    const d = SW_ACTS[a];
    if (!d) return '';
    // what the button says depends on the email (Read or Unread, Flag or Unflag…)
    const label = a === 'read' ? (it.seen ? 'Unread' : 'Read') : a === 'flag' ? (it.flagged ? 'Unflag' : 'Flag') : a === 'pin' ? (this._isPinned?.(it) ? 'Unpin' : 'Pin') : a === 'trash' ? 'Trash' : d.label;
    const icon = a === 'read' ? (it.seen ? ICON.unreadF : ICON.mailOpen) : ICON[d.icon] || '';
    return `<button class="${d.cls}" data-sw="${a}">${icon}<span>${esc(label)}</span></button>`;
  },

  _pg_swipes() {
    const el = this._simplePage('Swipes', '<div class="body"></div>');
    this._scrollTitle(el);
    const body = el.querySelector('.body');
    const name = (a) => a === 'none' ? 'None' : SW_ACTS[a]?.label || a;
    const slot = (key, i, val, canNone) => `<div class="gr icon-row" role="button" data-slot="${key}:${i}"><span class="gi" style="background:${val === 'none' ? 'var(--ce-fill)' : 'var(--ce-accent)'}">${val === 'none' ? '' : ICON[SW_ACTS[val]?.icon] || ''}</span><span class="gl">${i === -1 ? 'Long Swipe' : `Button ${i + 1}`}</span><span class="gv">${esc(name(val))}</span><span class="gch">${ICON.chevR}</span></div>`;
    const draw = () => {
      const sw = this._swipes();
      const r = [0, 1].map(i => slot('right', i, sw.right[i] || 'none', i > 0)).join('');
      const l = [0, 1, 2].map(i => slot('left', i, sw.left[i] || 'none', i > 0)).join('');
      body.innerHTML = `<div class="sh">Swipe Right</div><div class="sgroup">${r}${slot('long_right', -1, sw.long_right)}</div>
        <div class="sh" style="margin-top:20px">Swipe Left</div><div class="sgroup">${l}${slot('long_left', -1, sw.long_left)}</div>
        <div class="sfoot">A short swipe shows the buttons; a long swipe does the Long Swipe action straight away. Button 1 is nearest the edge you swipe from.</div>
        <div class="sgroup" style="margin-top:18px"><div class="gr blue" role="button" data-a="reset"><span class="gl">Use the Standard Swipes</span></div></div>
        <div class="sfoot">Your swipes follow you to every device.</div>`;
    };
    const save = async (swipes) => {
      try { const p = await this._call('prefs', { swipes }); this._s.prefs = p; draw(); this._refresh('view'); } catch (err) { this._err(err); }
    };
    el.addEventListener('click', async (e) => {
      if (e.target.closest('[data-a="back"]')) { this._back(); return; }
      if (e.target.closest('[data-a="reset"]')) { save({ right: ['read', 'pin'], left: [this._config.swipe_action === 'trash' ? 'trash' : 'archive', 'flag', 'more'], long_right: 'none', long_left: this._config.swipe_action === 'trash' ? 'trash' : 'archive' }); return; }
      const row = e.target.closest('[data-slot]');
      if (!row) return;
      const [key, idx] = row.dataset.slot.split(':'), i = +idx;
      const sw = this._swipes();
      const opts = Object.entries(SW_ACTS).filter(([, d]) => !d.needs || this._feat(d.needs));
      const cur = i === -1 ? sw[key] : (sw[key][i] || 'none');
      const items = [...((i === -1 || i > 0) ? [{ text: 'None', value: 'none', checked: cur === 'none' }] : []), ...opts.map(([k, d]) => ({ text: d.label, value: k, icon: d.icon, checked: cur === k }))];
      const v = await this._menu(row, items);
      if (!v) return;
      const next = { right: [...sw.right], left: [...sw.left], long_right: sw.long_right, long_left: sw.long_left };
      if (i === -1) next[key] = v;
      else {
        const arr = next[key];
        if (v === 'none') arr.splice(i);
        else { const at = arr.indexOf(v); if (at >= 0 && at !== i) arr.splice(at, 1); if (i >= arr.length) arr.push(v); else arr[i] = v; }
        next[key] = arr.slice(0, key === 'right' ? 2 : 3);
      }
      save(next);
    });
    draw();
    return { el, refresh: (what) => { if (['all', 'prefs', 'back'].includes(what)) draw(); } };
  },

  // ── Today ───────────────────────────────────────────────────────────
  _todayItems() {
    const s = this._s, now = new Date(), end = new Date(now); end.setHours(23, 59, 59, 999);
    const E = end.getTime(), pad = (n) => String(n).padStart(2, '0');
    const iso = `${now.getFullYear()}-${pad(now.getMonth() + 1)}-${pad(now.getDate())}`;
    const out = [];
    this._activeParcels().filter(p => p.expected === iso || p.status === 'out_for_delivery').forEach(p => out.push({ kind: 'parcel', id: p.id, title: p.item || p.retailer || 'A parcel', sub: p.status === 'out_for_delivery' ? 'Out for delivery' : `Arriving today${p.retailer && p.item ? ` · ${p.retailer}` : ''}` }));
    (s.reminders || []).filter(r => r.fired || r.at <= E).sort((a, b) => a.at - b.at).forEach(r => out.push({ kind: 'reminder', id: r.id, title: r.subject || '(No subject)', sub: r.fired ? `Reminder · ${whoShort((r.from || [])[0])}` : 'Reminder', at: r.fired ? 0 : r.at, ref: r }));
    (s.snoozed || []).filter(x => x.until <= E).forEach(x => out.push({ kind: 'snoozed', id: x.id, title: x.subject || '(No subject)', sub: `Back from Snooze · ${whoShort((x.from || [])[0])}`, at: x.until }));
    (s.appointments || []).filter(x => (x.start || '').slice(0, 10) === iso).forEach(x => out.push({ kind: 'appointment', id: x.id, title: x.title, sub: x.location || 'Appointment', at: (x.start || '').length > 10 ? x.at : 0 }));
    (s.bills || []).filter(x => !x.paid && x.due).forEach(x => {
      const d = Math.round((new Date(`${x.due}T00:00`) - new Date(`${iso}T00:00`)) / 86400000);
      if (d <= 3) out.push({ kind: 'bill', id: x.id, title: `${x.payee || 'A bill'}${x.amount != null ? ` · ${this._money(x)}` : ''}`, sub: d < 0 ? 'Overdue' : d === 0 ? 'Due today' : d === 1 ? 'Due tomorrow' : `Due in ${d} days` });
    });
    const todayIso = iso;
    this._findActive('travel').filter(o => o.start_at && o.start_at <= E).forEach(o => out.push({ kind: 'travel', id: o.id, title: this._findTitle('travel', o), sub: o.status === 'delayed' ? `Delayed${o.delay_minutes ? ` ${o.delay_minutes} min` : ''}` : o.status === 'changed' ? 'Changed' : 'Travel', at: o.start_at }));
    this._findActive('visits').filter(o => o.start_at && o.start_at <= E).forEach(o => out.push({ kind: 'visit', id: o.id, title: o.what || 'Home visit', sub: o.end_at ? `${o.company ? `${o.company} · ` : ''}until ${fmtTime(o.end_at, this._hass)}` : (o.company || 'Home visit'), at: o.start_at }));
    this._findActive('tickets').filter(o => o.start_at && o.start_at <= E).forEach(o => out.push({ kind: 'ticket', id: o.id, title: o.event, sub: o.doors_at ? `Doors ${fmtTime(o.doors_at, this._hass)}${o.venue ? ` · ${o.venue}` : ''}` : (o.venue || 'Tickets'), at: o.start_at }));
    this._findActive('returns').filter(o => o.return_by === todayIso && ['started', 'label_ready'].includes(o.status)).forEach(o => out.push({ kind: 'return', id: o.id, title: o.item, sub: 'Last day to send back' }));
    this._findActive('renewals').filter(o => o.renews === todayIso).forEach(o => out.push({ kind: 'renewal', id: o.id, title: o.what, sub: 'Renews today' }));
    this._findActive('council').filter(o => [o.date, o.action_by].includes(todayIso)).forEach(o => out.push({ kind: 'council', id: o.id, title: o.title, sub: o.action_by === todayIso ? 'Deadline today' : (COUNCIL_TOPIC[o.topic] || 'Today') }));
    for (const k of ['food', 'groceries']) {
      this._activeOrders(k).filter(o => o.when && o.when <= E).forEach(o => out.push({ kind: k === 'food' ? 'food' : 'grocery', id: o.id, title: this._orderTitle(o),
        sub: k === 'food' ? (o.method === 'collection' ? 'Ready to collect' : 'Food arriving') : (o.method === 'collection' ? 'Click and collect' : 'Supermarket delivery'), at: o.when }));
    }
    (s.nudges || []).forEach(n => out.push({ kind: 'followup', id: n.id, title: n.subject || '(No subject)', sub: `Follow up · ${whoShort((n.to || [])[0])}`, ref: n }));
    return out;
  },

  _todayHtml() {
    const items = this._todayItems();
    const icon = { parcel: 'parcel', reminder: 'remind', snoozed: 'snooze', followup: 'followup', appointment: 'appt', bill: 'bill', food: 'food', grocery: 'basket', travel: 'plane', visit: 'wrench', ticket: 'ticket', return: 'returnBox', renewal: 'renew', council: 'townhall' };
    const rows = items.slice(0, 5).map(x => `<div class="today-row" role="button" data-today="${x.kind}:${esc(x.id)}"><span class="ti ${x.kind}">${ICON[icon[x.kind]] || ''}</span><span class="tt">${esc(x.title)}<small>${esc(x.sub)}</small></span>${x.at ? `<span class="tw">${esc(fmtTime(x.at, this._hass))}</span>` : ''}</div>`).join('');
    return `<div class="today"><div class="today-h">${ICON.today}<span>Today</span>${items.length ? `<em>${items.length}</em>` : ''}</div>
      ${rows || '<div class="today-none">Nothing needs your attention today.</div>'}${items.length > 5 ? `<div class="today-more">and ${items.length - 5} more</div>` : ''}</div>`;
  },

  _todayOpen(key) {
    const [kind, ...rest] = key.split(':');
    const id = rest.join(':');
    const it = this._todayItems().find(x => x.kind === kind && x.id === id);
    if (!it) return;
    if (kind === 'parcel') { this._nav('parcels'); return; }
    if (kind === 'appointment') { this._nav('appointments'); return; }
    if (kind === 'bill') { this._nav('bills'); return; }
    if (kind === 'food') { this._nav('food'); return; }
    if (kind === 'grocery') { this._nav('groceries'); return; }
    const fk = { travel: 'travel', visit: 'visits', ticket: 'tickets', return: 'returns', renewal: 'renewals', council: 'council' }[kind];
    if (fk) { this._nav('finds', { kind: fk }); return; }
    if (kind === 'snoozed') { this._openSnoozed(id); return; }
    if (kind === 'reminder') { this._nav('reader', { account: it.ref.account, folder: it.ref.folder, uid: it.ref.muid }); return; }
    if (kind === 'followup') { if (it.ref.uid) this._nav('reader', { account: it.ref.account, folder: it.ref.folder, uid: it.ref.uid }); else this._nav('followups'); }
  },

  // ── keyboard shortcuts (a tablet or computer) ───────────────────────
  _kbWire(on) {
    if (!this._kbDown) {
      this._kbDown = (e) => this._kb(e);
      this._kbPtr = (e) => { this._kbActive = e.composedPath().includes(this); };
    }
    const m = on ? 'addEventListener' : 'removeEventListener';
    document[m]('keydown', this._kbDown);
    document[m]('pointerdown', this._kbPtr, true);
  },

  _kb(e) {
    if (e.defaultPrevented || e.ctrlKey || e.metaKey || e.altKey) return;
    if (!this._full && !this._kbActive) return;   // this card is the one you're using
    const t = e.composedPath()[0];
    if (t && (t.isContentEditable || /^(INPUT|TEXTAREA|SELECT)$/.test(t.tagName || ''))) return;
    if (this._root?.querySelector('.menu-wrap, .crow-ios-backdrop, .viewer') || this._root?.classList.contains('sheeting')) return;
    const k = e.key;
    if (k === '?') { e.preventDefault(); this._kbHelp(); return; }
    if (k === 'c') { e.preventDefault(); this._compose({}); return; }
    // the page the keys act on: the email if one's open, else the list
    const pages = this._stack.filter(p => p.el.style.display !== 'none');
    const pg = [...pages].reverse().find(p => p.kb);
    if (pg && pg.kb(k, e) !== false) e.preventDefault();
  },

  _pg_kbhelp() {
    const el = this._simplePage('Keyboard Shortcuts', `<div class="sgroup" style="padding:14px 16px"><div class="kb-list">${KB_KEYS.map(r => r.length === 1 ? `<div class="kh">${esc(r[0])}</div>` : `<kbd>${esc(r[0])}</kbd><span>${esc(r[1])}</span>`).join('')}</div></div>
      <div class="sfoot">For a tablet or computer with a keyboard. The keys work in the card you last tapped, or the one that's full screen.</div>`);
    this._scrollTitle(el);
    el.addEventListener('click', (e) => { if (e.target.closest('[data-a="back"]')) this._back(); });
    return { el };
  },

  _kbHelp() {
    this._sheet({
      title: 'Keyboard Shortcuts',
      body: `<div class="kb-list">${KB_KEYS.map(r => r.length === 1 ? `<div class="kh">${esc(r[0])}</div>` : `<kbd>${esc(r[0])}</kbd><span>${esc(r[1])}</span>`).join('')}</div>`,
    });
  },
});

// ── AI on top of the Inbox Tools: Appointments, Bills, Tidy-Up, the Morning Briefing,
// screener and subscription notes, signatures, Smart Snooze and follow-ups ──────
Object.assign(ICON, {
  bill: _s('<rect x="4.5" y="3" width="15" height="18" rx="2"/><path d="M8 8h8M8 12h8M8 16h5"/>'),
  appt: _s('<rect x="3.5" y="5" width="17" height="15" rx="2.5"/><path d="M3.5 10h17M8 3v4M16 3v4"/><circle cx="12" cy="15" r="1.6"/>'),
  sun: _s('<circle cx="12" cy="12" r="4"/><path d="M12 2.5v2.5M12 19v2.5M2.5 12H5M19 12h2.5M5.3 5.3l1.8 1.8M16.9 16.9l1.8 1.8M5.3 18.7l1.8-1.8M16.9 7.1l1.8-1.8"/>'),
  broom: _s('<path d="M14.5 2.5l-3.6 9.2"/><path d="M6.6 11.7h8.6l2.3 9H4.3z"/><path d="M8.6 15.7v5M11.6 15.7v5M14.6 15.7v5"/>'),
});

