  townhall: _s('<path d="M3 21h18M4.5 21V10M19.5 21V10M3 10h18L12 3.5z"/><path d="M8.5 21v-7M12 21v-7M15.5 21v-7"/>'),
  receipt: _s('<path d="M6 3h12v18l-2-1.4-2 1.4-2-1.4-2 1.4-2-1.4L6 21z"/><path d="M9 8h6M9 11.5h6M9 15h4"/>'),
